window.COLLECTIONS = [{"id": "cy", "name": "600个绝美的诗词成语，每一个背后都有故事"}];
window.ENTRIES = [{"id": 1, "collection": "cy", "term": "浮生若梦", "chars": 4, "pinyin": "", "source": "李白《春夜宴从弟桃花园序》", "meaning": "*夫天地者，万物之逆旅；光阴者，百代之过客。而浮生若梦，为欢几何？李白说：既然人生如梦，那就抓紧行乐。*", "category": "*一、光阴如流水"}, {"id": 2, "collection": "cy", "term": "坠兔收光", "chars": 4, "pinyin": "", "source": "明·李昌祺《剪灯余话》", "meaning": "*古人说月中有玉兔，月落便是\"坠兔收光\"。月色收起来的时候，一夜也走到头了。*", "category": "*一、光阴如流水"}, {"id": 3, "collection": "cy", "term": "红炉点雪", "chars": 4, "pinyin": "", "source": "禅宗语录", "meaning": "*红红的炉火，一点雪落上去，瞬间就化。比喻一经指点，立刻领悟。也像极了转瞬即逝的缘分。*", "category": "*一、光阴如流水"}, {"id": 4, "collection": "cy", "term": "星霜荏苒", "chars": 4, "pinyin": "", "source": "温庭筠《寄崔先生》", "meaning": "*星霜，是年岁的代称。星星转了一圈又一圈，霜降了一场又一场，鬓边的白发就多了。*", "category": "*一、光阴如流水"}, {"id": 5, "collection": "cy", "term": "岁聿云暮", "chars": 4, "pinyin": "", "source": "《诗经·小雅·小明》", "meaning": "*一年快要到头了。最简单的四个字，却藏着中国人对年关最深沉的感怀。*", "category": "*一、光阴如流水"}, {"id": 6, "collection": "cy", "term": "生年不满百，常怀千岁忧", "chars": 10, "pinyin": "", "source": "《古诗十九首》", "meaning": "*人生连一百岁都难满，却常常为千年之后的事忧愁。想开点，快乐才是正经事。*", "category": "*一、光阴如流水"}, {"id": 7, "collection": "cy", "term": "星离雨散", "chars": 4, "pinyin": "", "source": "李白《忆旧游寄谯郡元参军》", "meaning": "*群星离散，骤雨飘散。聚时有多热闹，散时就有多冷清。*", "category": "*一、光阴如流水"}, {"id": 8, "collection": "cy", "term": "逝者如斯", "chars": 4, "pinyin": "", "source": "《论语·子罕》", "meaning": "*子在川上曰：逝者如斯夫，不舍昼夜。孔子站在河边，把时间看成了流水。*", "category": "*一、光阴如流水"}, {"id": 9, "collection": "cy", "term": "人生到处知何似，应似飞鸿踏雪泥", "chars": 14, "pinyin": "", "source": "苏轼《和子由渑池怀旧》", "meaning": "*人生这趟旅程，到哪里去？就像鸿雁踏雪，脚印留下又消失，往事如烟。*", "category": "*一、光阴如流水"}, {"id": 10, "collection": "cy", "term": "寒来暑往", "chars": 4, "pinyin": "", "source": "《周易·系辞下》", "meaning": "*寒往则暑来，暑往则寒来。天地有序，四季轮回，最朴素的宇宙观。*", "category": "*一、光阴如流水"}, {"id": 11, "collection": "cy", "term": "珠流璧转", "chars": 4, "pinyin": "", "source": "古典诗文常用语", "meaning": "*时光如珠玉流转，圆润、珍贵，又头也不回。*", "category": "*一、光阴如流水"}, {"id": 12, "collection": "cy", "term": "星奔川骛", "chars": 4, "pinyin": "", "source": "南朝梁·刘孝标《广绝交论》", "meaning": "*像流星飞驰，像江河奔涌。说的是时间之快，也是人生之忙。*", "category": "*一、光阴如流水"}, {"id": 13, "collection": "cy", "term": "日月如梭", "chars": 4, "pinyin": "", "source": "明清小说常用语", "meaning": "***太阳和月亮像织布梭子一样交替往来，形容时间过得飞快。***", "category": "*一、光阴如流水"}, {"id": 14, "collection": "cy", "term": "年年岁岁花相似，岁岁年年人不同", "chars": 14, "pinyin": "", "source": "刘希夷《代悲白头翁》", "meaning": "*花还是那花，人已不是那人。最扎心的一句，道尽了光阴。*", "category": "*一、光阴如流水"}, {"id": 15, "collection": "cy", "term": "桃李春风一杯酒，江湖夜雨十年灯", "chars": 14, "pinyin": "", "source": "黄庭坚《寄黄几复》", "meaning": "*一杯酒敬当年春风，十年灯照今夜江湖。时间的重量，都在这两句里。*", "category": "*一、光阴如流水"}, {"id": 16, "collection": "cy", "term": "光阴似箭", "chars": 4, "pinyin": "", "source": "《增广贤文》", "meaning": "***光阴像射出的箭，转瞬即逝，一去不回。***", "category": "*一、光阴如流水"}, {"id": 17, "collection": "cy", "term": "白云苍狗", "chars": 4, "pinyin": "", "source": "杜甫《可叹》", "meaning": "*天上白云，转眼变成苍狗。世事无常，翻覆只在须臾之间。*", "category": "*一、光阴如流水"}, {"id": 18, "collection": "cy", "term": "岁月不居，时节如流", "chars": 8, "pinyin": "", "source": "孔融《论盛孝章书》", "meaning": "***岁月不停留，时节像流水一样奔去。孔融劝人珍惜时光，抓紧建功立业。***", "category": "*一、光阴如流水"}, {"id": 19, "collection": "cy", "term": "雪泥鸿爪", "chars": 4, "pinyin": "", "source": "苏轼《和子由渑池怀旧》", "meaning": "*人生到处知何似，应似飞鸿踏雪泥。鸿雁踏雪留痕，雪化痕消，人之一生也不过如此。*", "category": "*一、光阴如流水"}, {"id": 20, "collection": "cy", "term": "光阴荏苒", "chars": 4, "pinyin": "", "source": "晋·陶渊明《杂诗》", "meaning": "***时光渐渐流逝。荏苒，形容时间不知不觉地过去。***", "category": "*一、光阴如流水"}, {"id": 21, "collection": "cy", "term": "似水流年", "chars": 4, "pinyin": "", "source": "明·汤显祖《牡丹亭》", "meaning": "*则为你如花美眷，似水流年。花再美，也拗不过流水一样的年华。*", "category": "*一、光阴如流水"}, {"id": 22, "collection": "cy", "term": "盛年不重来，一日难再晨", "chars": 10, "pinyin": "", "source": "陶渊明《杂诗》", "meaning": "*最好的年纪不会再来，一天的清晨不会重复。与其叹息，不如趁早出发。*", "category": "*一、光阴如流水"}, {"id": 23, "collection": "cy", "term": "白驹过隙", "chars": 4, "pinyin": "", "source": "《庄子·知北游》", "meaning": "*人生天地之间，若白驹之过隙，忽然而已。一匹白马从门缝前一闪而过，一生就这样过去了。*", "category": "*一、光阴如流水"}, {"id": 24, "collection": "cy", "term": "及时当勉励，岁月不待人", "chars": 10, "pinyin": "", "source": "陶渊明《杂诗》", "meaning": "*盛年不重来，一日难再晨。陶渊明劝的不是别人，是我们每一个人。*", "category": "*一、光阴如流水"}, {"id": 25, "collection": "cy", "term": "逝水流年", "chars": 4, "pinyin": "", "source": "古人常用语", "meaning": "*时光像水一样流走，抓不住，也留不住。回头看，年少的影子还在昨天。*", "category": "*一、光阴如流水"}, {"id": 26, "collection": "cy", "term": "流光容易把人抛，红了樱桃，绿了芭蕉", "chars": 15, "pinyin": "", "source": "蒋捷《一剪梅·舟过吴江》", "meaning": "*时光跑得太快，快得你抓不住它。等樱桃红了、芭蕉绿了，你才惊觉：又是一年。最温柔的一句惜时。*", "category": "*一、光阴如流水"}, {"id": 27, "collection": "cy", "term": "最是人间留不住，朱颜辞镜花辞树", "chars": 14, "pinyin": "", "source": "王国维《蝶恋花·阅尽天涯离别苦》", "meaning": "*红颜老去，花朵凋零，人间最留不住的就是这两样。王国维一句，写尽了美人迟暮与芳华易逝。*", "category": "*一、光阴如流水"}, {"id": 28, "collection": "cy", "term": "闲云潭影日悠悠，物换星移几度秋", "chars": 14, "pinyin": "", "source": "王勃《滕王阁诗》", "meaning": "*云影在潭水里晃了一整天，天上的星斗换了几度春秋。王勃站在滕王阁上，看见的是时间本身。*", "category": "*一、光阴如流水"}, {"id": 29, "collection": "cy", "term": "君不见，黄河之水天上来，奔流到海不复回", "chars": 17, "pinyin": "", "source": "李白《将进酒》", "meaning": "*黄河从天边奔涌而来，一路向东，再不回头。李白说：时光如水，一去不回，所以更要痛快地活。*", "category": "*一、光阴如流水"}, {"id": 30, "collection": "cy", "term": "花开堪折直须折，莫待无花空折枝", "chars": 14, "pinyin": "", "source": "唐·杜秋娘《金缕衣》", "meaning": "**花开了该折就折，别等花谢了只剩空枝。劝少年惜时，也劝人趁早抓住眼前。**", "category": "*一、光阴如流水"}, {"id": 31, "collection": "cy", "term": "时不我待", "chars": 4, "pinyin": "", "source": "《论语·阳货》", "meaning": "***时间不会等待我们。岁月不等人，要抓紧眼前。***", "category": "*一、光阴如流水"}, {"id": 32, "collection": "cy", "term": "无可奈何花落去，似曾相识燕归来", "chars": 14, "pinyin": "", "source": "晏殊《浣溪沙》", "meaning": "*花落是无可奈何，燕归是似曾相识。晏殊用十个字，写尽了时间的流逝与人事的循环。*", "category": "*一、光阴如流水"}, {"id": 33, "collection": "cy", "term": "夕阳无限好，只是近黄昏", "chars": 10, "pinyin": "", "source": "李商隐《登乐游原》", "meaning": "*夕阳美到了极致，可惜已近黄昏。世间最好的东西，往往也走得最快。*", "category": "*一、光阴如流水"}, {"id": 34, "collection": "cy", "term": "韶华不为少年留", "chars": 7, "pinyin": "", "source": "秦观《江城子》", "meaning": "***美好的年华不会为少年停留。秦观叹春，叹的是留不住的青春。***", "category": "*一、光阴如流水"}, {"id": 35, "collection": "cy", "term": "少壮不努力，老大徒伤悲", "chars": 10, "pinyin": "", "source": "汉乐府《长歌行》", "meaning": "*年少时不肯用功，老了只能白白悲伤。最直白的一句劝学，劝了中国人两千年。*", "category": "*一、光阴如流水"}, {"id": 36, "collection": "cy", "term": "人生天地间，忽如远行客", "chars": 10, "pinyin": "", "source": "《古诗十九首·青青陵上柏》", "meaning": "*人在天地之间，就像匆匆赶路的远行客。来是偶然，走是必然，中间全是风景。*", "category": "*一、光阴如流水"}, {"id": 37, "collection": "cy", "term": "今人不见古时月，今月曾经照古人", "chars": 14, "pinyin": "", "source": "李白《把酒问月》", "meaning": "*月亮还是那个月亮，看月亮的人换了一茬又一茬。李白举杯问月，问出了时间的苍茫。*", "category": "*一、光阴如流水"}, {"id": 38, "collection": "cy", "term": "长绳系日", "chars": 4, "pinyin": "", "source": "晋·傅玄《九曲歌》", "meaning": "***想用一根长绳子把太阳拴住，让时光停下。痴心妄想里，藏着对光阴的深情。***", "category": "*一、光阴如流水"}, {"id": 39, "collection": "cy", "term": "天若有情天亦老", "chars": 7, "pinyin": "", "source": "李贺《金铜仙人辞汉歌》", "meaning": "*天若有感情，也会因这兴亡而老去。李贺一句，让\"无情\"成了天地间最大的慈悲。*", "category": "*一、光阴如流水"}, {"id": 40, "collection": "cy", "term": "树犹如此，人何以堪", "chars": 8, "pinyin": "", "source": "《世说新语·言语》", "meaning": "*桓温北伐路过金城，见当年手植的柳树已十围粗，慨然泪下：树都这样了，人怎么受得了？时间的重量，压在一棵树上。*", "category": "*一、光阴如流水"}, {"id": 41, "collection": "cy", "term": "江畔何人初见月？江月何年初照人", "chars": 14, "pinyin": "", "source": "张若虚《春江花月夜》", "meaning": "*第一个在江边看见月亮的是谁？月亮又是哪一年第一次照到人？张若虚一问，问出了宇宙的孤独。*", "category": "*一、光阴如流水"}, {"id": 42, "collection": "cy", "term": "弹指之间", "chars": 4, "pinyin": "", "source": "佛教经典《楞严经》", "meaning": "***一弹指的工夫。佛家说二十念为一瞬，二十瞬为一弹指，时间快得惊人。***", "category": "*一、光阴如流水"}, {"id": 43, "collection": "cy", "term": "东隅已逝，桑榆非晚", "chars": 8, "pinyin": "", "source": "王勃《滕王阁序》", "meaning": "*早晨已经过去了，傍晚还不算晚。王勃说：错过了日出，还能赶上晚霞——任何时候开始都不迟。*", "category": "*一、光阴如流水"}, {"id": 44, "collection": "cy", "term": "沧海桑田", "chars": 4, "pinyin": "", "source": "晋·葛洪《神仙传》", "meaning": "*麻姑说：我见过东海三次变成桑田。时间的力量大到，连海都耐不住它的性子。*", "category": "*一、光阴如流水"}, {"id": 45, "collection": "cy", "term": "物是人非事事休，欲语泪先流", "chars": 12, "pinyin": "", "source": "李清照《武陵春》", "meaning": "*东西还是老样子，人已经不是那批人。李清照想说什么，话没出口，泪先流了。*", "category": "*一、光阴如流水"}, {"id": 46, "collection": "cy", "term": "浮生若寄", "chars": 4, "pinyin": "", "source": "《古诗十九首·驱车上东门》", "meaning": "***人生就像暂时寄居在世间。既然短暂，更该活得尽兴。***", "category": "*一、光阴如流水"}, {"id": 47, "collection": "cy", "term": "流水落花春去也，天上人间", "chars": 11, "pinyin": "", "source": "李煜《浪淘沙令》", "meaning": "*春去了，花落了，像流水一样不再回来。从天上到人间，不过一转身的距离。*", "category": "*一、光阴如流水"}, {"id": 48, "collection": "cy", "term": "春花秋月何时了？往事知多少", "chars": 12, "pinyin": "", "source": "李煜《虞美人》", "meaning": "*春花年年开，秋月夜夜明，什么时候才是个头？李煜问月，问的是回不去的故国与年华。*", "category": "*一、光阴如流水"}, {"id": 49, "collection": "cy", "term": "春宵一刻值千金，花有清香月有阴", "chars": 14, "pinyin": "", "source": "苏轼《春宵》", "meaning": "*春天的夜晚，一刻就值一千金——花有香气，月有影子，这样的良辰，稍纵即逝。*", "category": "*一、光阴如流水"}, {"id": 50, "collection": "cy", "term": "今我不乐，日月其除", "chars": 8, "pinyin": "", "source": "《诗经·唐风·蟋蟀》", "meaning": "**今日我不及时行乐，日月就要过去了。古人用诗提醒：好时光不会等人。**", "category": "*一、光阴如流水"}, {"id": 51, "collection": "cy", "term": "老骥伏枥，志在千里；烈士暮年，壮心不已", "chars": 16, "pinyin": "", "source": "曹操《龟虽寿》", "meaning": "*老马趴在槽边，心里想的还是千里之外。曹操说：人老了，心不能老，壮心到死不休。*", "category": "*一、光阴如流水"}, {"id": 52, "collection": "cy", "term": "日居月诸，胡迭而微", "chars": 8, "pinyin": "", "source": "《诗经·邶风·柏舟》", "meaning": "**太阳月亮啊，为何轮番黯淡无光？诗人借日月感叹人生困顿、岁月流逝。**", "category": "*一、光阴如流水"}, {"id": 53, "collection": "cy", "term": "老去光阴速可惊，鬓华虽改心无改", "chars": 14, "pinyin": "", "source": "欧阳修《采桑子》", "meaning": "**老去的时光快得惊人，鬓发虽白，心志不改。欧阳修看淡年龄，看重心境。**", "category": "*一、光阴如流水"}, {"id": 54, "collection": "cy", "term": "白发三千丈，缘愁似个长", "chars": 10, "pinyin": "", "source": "李白《秋浦歌》", "meaning": "*白发三千丈，因为愁绪也这么长。李白把愁写成了长度单位，夸张得可爱，也悲凉得彻底。*", "category": "*一、光阴如流水"}, {"id": 55, "collection": "cy", "term": "日往月来", "chars": 4, "pinyin": "", "source": "《周易·系辞下》", "meaning": "***太阳落下月亮升起，一天天循环往复，时间就这样流走了。***", "category": "*一、光阴如流水"}, {"id": 56, "collection": "cy", "term": "寒暑易节", "chars": 4, "pinyin": "", "source": "《列子·汤问》", "meaning": "***寒暑变换，季节更替。愚公移山，靠的就是年复一年的坚持。***", "category": "*一、光阴如流水"}, {"id": 57, "collection": "cy", "term": "光景不待人，须臾发成丝", "chars": 10, "pinyin": "", "source": "李白《相逢行》", "meaning": "*光景不等人，一眨眼的工夫，头发就白了。李白把时间的残酷，写成了照镜子的日常。*", "category": "*一、光阴如流水"}, {"id": 58, "collection": "cy", "term": "春眠不觉晓，处处闻啼鸟", "chars": 10, "pinyin": "", "source": "孟浩然《春晓》", "meaning": "*春夜好睡，一觉醒来天都亮了，窗外到处是鸟叫。最清新的惜春诗——睡过去了，春天就少了半截。*", "category": "*一、光阴如流水"}, {"id": 59, "collection": "cy", "term": "今朝有酒今朝醉，明日愁来明日愁", "chars": 14, "pinyin": "", "source": "罗隐《自遣》", "meaning": "*今天有酒今天就喝醉，明天的烦恼明天再说。罗隐的及时行乐，是被现实逼出来的洒脱。*", "category": "*一、光阴如流水"}, {"id": 60, "collection": "cy", "term": "爆竹声中一岁除，春风送暖入屠苏", "chars": 14, "pinyin": "", "source": "王安石《元日》", "meaning": "*爆竹声里，旧年走了；春风一吹，新年来了。王安石写元日，写的是万象更新的底气。*", "category": "*一、光阴如流水"}, {"id": 61, "collection": "cy", "term": "独在异乡为异客，每逢佳节倍思亲", "chars": 14, "pinyin": "", "source": "王维《九月九日忆山东兄弟》", "meaning": "*一个人在外地当异客，每到节日就更想家。王维十四岁写下的句子，成了所有游子的乡愁。*", "category": "*一、光阴如流水"}, {"id": 62, "collection": "cy", "term": "不知天上宫阙，今夕是何年", "chars": 11, "pinyin": "", "source": "苏轼《水调歌头》", "meaning": "*不知道天上的宫殿，今晚是什么年月。苏轼问天，问的是时间在别处的模样。*", "category": "*一、光阴如流水"}, {"id": 63, "collection": "cy", "term": "春色满园关不住，一枝红杏出墙来", "chars": 14, "pinyin": "", "source": "叶绍翁《游园不值》", "meaning": "*满园春色关不住，一枝红杏探出墙来。春天是关不住的，它总有办法溜出来给你看。*", "category": "*一、光阴如流水"}, {"id": 64, "collection": "cy", "term": "等闲识得东风面，万紫千红总是春", "chars": 14, "pinyin": "", "source": "朱熹《春日》", "meaning": "*随处都能认出东风的面孔，万紫千红都是春天。朱熹把春天写成了看得见的道理。*", "category": "*一、光阴如流水"}, {"id": 65, "collection": "cy", "term": "不知细叶谁裁出，二月春风似剪刀", "chars": 14, "pinyin": "", "source": "贺知章《咏柳》", "meaning": "*细细的柳叶是谁裁出来的？二月的春风，就是那把剪刀。春天的手艺，精巧得让人叹服。*", "category": "*一、光阴如流水"}, {"id": 66, "collection": "cy", "term": "竹外桃花三两枝，春江水暖鸭先知", "chars": 14, "pinyin": "", "source": "苏轼《惠崇春江晚景》", "meaning": "*竹子外头开了三两枝桃花，鸭子下水了，最先知道江水变暖。春天来了，最先知道的总是水里的家伙。*", "category": "*一、光阴如流水"}, {"id": 67, "collection": "cy", "term": "好雨知时节，当春乃发生", "chars": 10, "pinyin": "", "source": "杜甫《春夜喜雨》", "meaning": "*好雨懂得时节，春天一到就下了起来。杜甫说：雨也通人性，来得刚刚好。*", "category": "*一、光阴如流水"}, {"id": 68, "collection": "cy", "term": "日出江花红胜火，春来江水绿如蓝", "chars": 14, "pinyin": "", "source": "白居易《忆江南》", "meaning": "*日出时江花红得像火，春天里江水绿得胜过蓝草。白居易忆江南，忆的是春天最烈的颜色。*", "category": "*一、光阴如流水"}, {"id": 69, "collection": "cy", "term": "一年之计在于春", "chars": 7, "pinyin": "", "source": "《增广贤文》", "meaning": "***一年的计划要在春天就定好。开头把握住了，整年才有奔头。***", "category": "*一、光阴如流水"}, {"id": 70, "collection": "cy", "term": "春华秋实", "chars": 4, "pinyin": "", "source": "《后汉书·崔骃传》", "meaning": "***春天开花，秋天结果。比喻文采与德行兼备，也指付出终有回报。***", "category": "*一、光阴如流水"}, {"id": 71, "collection": "cy", "term": "斗转星移", "chars": 4, "pinyin": "", "source": "元·马致远《陈抟高卧》", "meaning": "***北斗转了方向，星辰移动了位置。时间流逝，世事变迁，尽在这四个字里。***", "category": "*一、光阴如流水"}, {"id": 72, "collection": "cy", "term": "时光只解催人老，不信多情，长恨离亭", "chars": 15, "pinyin": "", "source": "晏殊《采桑子》", "meaning": "*时光只懂得催人变老，不懂人间多情。晏殊站在离亭边，恨时间无情，更恨聚散无常。* *。*", "category": "*一、光阴如流水"}, {"id": 73, "collection": "cy", "term": "万象更新", "chars": 4, "pinyin": "", "source": "清·曹雪芹《红楼梦》", "meaning": "***万物都换上了新气象。新年伊始，一切都是重新开始的模样。***", "category": "*一、光阴如流水"}, {"id": 74, "collection": "cy", "term": "此生此夜不长好，明月明年何处看", "chars": 14, "pinyin": "", "source": "苏轼《阳关曲·中秋月》", "meaning": "*这一生这样的好夜晚不多，明年中秋，又不知在哪里看月亮。苏轼把良辰美景，都看成了稍纵即逝。*", "category": "*一、光阴如流水"}, {"id": 75, "collection": "cy", "term": "今夕何夕，见此良人", "chars": 8, "pinyin": "", "source": "《诗经·唐风·绸缪》", "meaning": "*今天是什么好日子，竟让我遇见了这么好的人。《诗经》里最惊喜的一句——良辰美景，佳人当前，时间都慢了。*", "category": "*一、光阴如流水"}, {"id": 76, "collection": "cy", "term": "天不老，情难绝。心似双丝网，中有千千结", "chars": 16, "pinyin": "", "source": "张先《千秋岁》", "meaning": "*天不会老，情不会断。心像双丝织成的网，结着千千个解不开的结。*", "category": "*二、情深缘浅"}, {"id": 77, "collection": "cy", "term": "愿得一心人，白头不相离", "chars": 10, "pinyin": "", "source": "卓文君《白头吟》", "meaning": "*卓文君为了司马相如当垆卖酒，也用这首诗守住了一生的誓言。*", "category": "*二、情深缘浅"}, {"id": 78, "collection": "cy", "term": "相见时难别亦难，东风无力百花残", "chars": 14, "pinyin": "", "source": "李商隐《无题》", "meaning": "*见一面很难，分别更难。春天都走到了尽头，像极了我们的结局。*", "category": "*二、情深缘浅"}, {"id": 79, "collection": "cy", "term": "天长地久有时尽，此恨绵绵无绝期", "chars": 14, "pinyin": "", "source": "白居易《长恨歌》", "meaning": "*天地都有穷尽的时候，唯有遗憾没有尽头。*", "category": "*二、情深缘浅"}, {"id": 80, "collection": "cy", "term": "在天愿作比翼鸟，在地愿为连理枝", "chars": 14, "pinyin": "", "source": "白居易《长恨歌》", "meaning": "***在天上愿做比翼双飞的鸟，在地上愿做枝叶相连的树。唐明皇与杨贵妃的誓言，成了中国人对爱情最重的承诺。***", "category": "*二、情深缘浅"}, {"id": 81, "collection": "cy", "term": "人面桃花", "chars": 4, "pinyin": "", "source": "崔护《题都城南庄》", "meaning": "*去年今日此门中，人面桃花相映红。只差一步，便是错过一生。*", "category": "*二、情深缘浅"}, {"id": 82, "collection": "cy", "term": "人生若只如初见，何事秋风悲画扇", "chars": 14, "pinyin": "", "source": "纳兰性德《木兰花令》", "meaning": "*如果一切都停在初见那一刻，该多好。后来所有的遗憾，都在这一句里。*", "category": "*二、情深缘浅"}, {"id": 83, "collection": "cy", "term": "盈盈一水间，脉脉不得语", "chars": 10, "pinyin": "", "source": "《古诗十九首·迢迢牵牛星》", "meaning": "***银河之水清浅，两人却只能相望，说不出话。最美的距离，也是最远的距离。***", "category": "*二、情深缘浅"}, {"id": 84, "collection": "cy", "term": "红豆生南国，春来发几枝", "chars": 10, "pinyin": "", "source": "王维《相思》", "meaning": "*劝君多采撷，此物最相思。一颗红豆，就是一颗想你的心。*", "category": "*二、情深缘浅"}, {"id": 85, "collection": "cy", "term": "曾经沧海难为水，除却巫山不是云", "chars": 14, "pinyin": "", "source": "元稹《离思》", "meaning": "*见过沧海，别处的水便不叫水；见过巫山的云，别处的云便不叫云。用尽一生的偏爱。*", "category": "*二、情深缘浅"}, {"id": 86, "collection": "cy", "term": "身无彩凤双飞翼，心有灵犀一点通", "chars": 14, "pinyin": "", "source": "李商隐《无题》", "meaning": "*虽然没有翅膀飞到你身边，但你心里想什么，我全都懂。*", "category": "*二、情深缘浅"}, {"id": 87, "collection": "cy", "term": "我住长江头，君住长江尾", "chars": 10, "pinyin": "", "source": "李之仪《卜算子》", "meaning": "*日日思君不见君，共饮长江水。同一条江，同一个相思。*", "category": "*二、情深缘浅"}, {"id": 88, "collection": "cy", "term": "山有木兮木有枝，心悦君兮君不知", "chars": 14, "pinyin": "", "source": "《越人歌》", "meaning": "*山上有树，树上有枝，我心里喜欢你，你却不知道。千古暗恋，尽在这一句。*", "category": "*二、情深缘浅"}, {"id": 89, "collection": "cy", "term": "月上柳梢头，人约黄昏后", "chars": 10, "pinyin": "", "source": "欧阳修《生查子·元夕》", "meaning": "*月亮爬上柳梢，黄昏的约定。元宵夜的浪漫，是古人的情人节。*", "category": "*二、情深缘浅"}, {"id": 90, "collection": "cy", "term": "西窗剪烛", "chars": 4, "pinyin": "", "source": "李商隐《夜雨寄北》", "meaning": "*何当共剪西窗烛，却话巴山夜雨时。把重逢的期待，剪成灯花。*", "category": "*二、情深缘浅"}, {"id": 91, "collection": "cy", "term": "迢迢牵牛星，皎皎河汉女", "chars": 10, "pinyin": "", "source": "《古诗十九首》", "meaning": "***牵牛星遥远，织女星明亮。隔着银河的两个人，一年才见一次。***", "category": "*二、情深缘浅"}, {"id": 92, "collection": "cy", "term": "晓风残月", "chars": 4, "pinyin": "", "source": "柳永《雨霖铃》", "meaning": "*今宵酒醒何处？杨柳岸，晓风残月。酒醒了，人散了，只剩清晨的风和将落的月。*", "category": "*二、情深缘浅"}, {"id": 93, "collection": "cy", "term": "夜月一帘幽梦，春风十里柔情", "chars": 12, "pinyin": "", "source": "秦观《八六子》", "meaning": "***月夜下的一场幽梦，春风里的十里柔情。回忆里最柔软的部分，都被秦观写尽了。***", "category": "*二、情深缘浅"}, {"id": 94, "collection": "cy", "term": "问世间情为何物，直教生死相许", "chars": 13, "pinyin": "", "source": "元好问《摸鱼儿》", "meaning": "*元好问买下一对殉情的大雁，埋了它，写下这千古一问。情到深处，生死都轻。*", "category": "*二、情深缘浅"}, {"id": 95, "collection": "cy", "term": "一日不见，如三秋兮", "chars": 8, "pinyin": "", "source": "《诗经·王风·采葛》", "meaning": "*一天没见到你，像过了三个秋天。古人早就把\"想你\"说到了极致。*", "category": "*二、情深缘浅"}, {"id": 96, "collection": "cy", "term": "晓看天色暮看云，行也思君，坐也思君", "chars": 15, "pinyin": "", "source": "唐寅《一剪梅》", "meaning": "*从早到晚，走路坐着，满脑子都是你。想一个人，藏都藏不住。*", "category": "*二、情深缘浅"}, {"id": 97, "collection": "cy", "term": "山盟虽在，锦书难托", "chars": 8, "pinyin": "", "source": "陆游《钗头凤》", "meaning": "***当年的山盟海誓还在，想寄给你的信却再也递不出去。陆游与唐琬，一别就是一生。***", "category": "*二、情深缘浅"}, {"id": 98, "collection": "cy", "term": "结发为夫妻，恩爱两不疑", "chars": 10, "pinyin": "", "source": "苏武《留别妻》", "meaning": "**结为夫妻，恩爱不疑。苏武出使匈奴前写给妻子的诗，是汉代最深情的情书。**", "category": "*一、光阴如流水"}, {"id": 99, "collection": "cy", "term": "两情若是久长时，又岂在朝朝暮暮", "chars": 14, "pinyin": "", "source": "秦观《鹊桥仙》", "meaning": "*只要情比金坚，隔着银河也是团圆。给所有异地恋最好的安慰。*", "category": "*二、情深缘浅"}, {"id": 100, "collection": "cy", "term": "蒹葭苍苍，白露为霜。所谓伊人，在水一方", "chars": 16, "pinyin": "", "source": "《诗经·秦风·蒹葭》", "meaning": "*秋天水边，芦苇苍苍。那个人在水的那一边，可望而不可即，美了一千年。*", "category": "*二、情深缘浅"}, {"id": 101, "collection": "cy", "term": "春蚕到死丝方尽，蜡炬成灰泪始干", "chars": 14, "pinyin": "", "source": "李商隐《无题》", "meaning": "*春蚕到死才把丝吐完，蜡烛烧成灰泪才流干。李商隐说：相思和奉献，都要到生命最后一刻。*", "category": "*二、情深缘浅"}, {"id": 102, "collection": "cy", "term": "相思本是无凭语，莫向花笺费泪行", "chars": 14, "pinyin": "", "source": "晏几道《鹧鸪天》", "meaning": "**相思本就没有语言能说清，别对着信纸空费眼泪。**", "category": "*一、光阴如流水"}, {"id": 103, "collection": "cy", "term": "多情自古伤离别，更那堪，冷落清秋节", "chars": 15, "pinyin": "", "source": "柳永《雨霖铃》", "meaning": "*多情的人自古就怕离别，何况是在冷清的秋天。柳永把离别的凄凉写到了极致。*", "category": "*二、情深缘浅"}, {"id": 104, "collection": "cy", "term": "从别后，忆相逢，几回魂梦与君同", "chars": 13, "pinyin": "", "source": "晏几道《鹧鸪天》", "meaning": "*自从离别后，总想起相逢的日子，多少次在梦里和你在一起。晏几道把相思写进了梦里。*", "category": "*二、情深缘浅"}, {"id": 105, "collection": "cy", "term": "金风玉露一相逢，便胜却人间无数", "chars": 14, "pinyin": "", "source": "秦观《鹊桥仙》", "meaning": "*金风玉露里的一次相逢，就胜过人间无数次的朝夕相处。秦观把牛郎织女写得无比高贵。*", "category": "*二、情深缘浅"}, {"id": 106, "collection": "cy", "term": "南风知我意，吹梦到西洲", "chars": 10, "pinyin": "", "source": "《西洲曲》", "meaning": "*南风啊，你若懂我的心意，就把我的梦吹到西洲去吧。南朝民歌里最深情的托付。*", "category": "*二、情深缘浅"}, {"id": 107, "collection": "cy", "term": "上邪！我欲与君相知，长命无绝衰。山无陵，江水为竭，冬雷震震，夏雨雪，天地合，乃敢与君绝", "chars": 35, "pinyin": "", "source": "《汉乐府·上邪》", "meaning": "*除非高山夷平、江水干涸、冬天打雷、夏天下雪、天地合拢，才敢和你分开。汉代女子最烈的誓言。*", "category": "*二、情深缘浅"}, {"id": 108, "collection": "cy", "term": "关关雎鸠，在河之洲。窈窕淑女，君子好逑", "chars": 16, "pinyin": "", "source": "《诗经·周南·关雎》", "meaning": "*雎鸠在河洲上鸣叫，美丽贤淑的女子，是君子的好配偶。《诗经》第一首，写的就是爱情的开始。*", "category": "*二、情深缘浅"}, {"id": 109, "collection": "cy", "term": "记得绿罗裙，处处怜芳草", "chars": 10, "pinyin": "", "source": "牛希济《生查子》", "meaning": "**记得你穿的绿罗裙，从此看到处处芳草都心生怜惜。因为绿草像你的裙色。**", "category": "*一、光阴如流水"}, {"id": 110, "collection": "cy", "term": "相思一夜情多少，地角天涯未是长", "chars": 14, "pinyin": "", "source": "张仲素《燕子楼》", "meaning": "**一夜相思的情意有多少？比地角天涯还要长。**", "category": "*一、光阴如流水"}, {"id": 111, "collection": "cy", "term": "平生不会相思，才会相思，便害相思", "chars": 14, "pinyin": "", "source": "徐再思《折桂令·春情》", "meaning": "**一辈子不会相思，刚学会相思，就害了相思。把相思初体验写绝了。**", "category": "*一、光阴如流水"}, {"id": 112, "collection": "cy", "term": "青青子衿，悠悠我心", "chars": 8, "pinyin": "", "source": "《诗经·郑风·子衿》", "meaning": "*你那青青的衣领，悠悠地牵动我的心。女子在城楼等心上人，等得心焦又甜蜜。*", "category": "*二、情深缘浅"}, {"id": 113, "collection": "cy", "term": "忆君心似西江水，日夜东流无歇时", "chars": 14, "pinyin": "", "source": "鱼玄机《江陵愁望有寄》", "meaning": "***想你的心像西江的水，日夜东流，从不停歇。唐代才女鱼玄机的相思，奔涌而不可收。***", "category": "*二、情深缘浅"}, {"id": 114, "collection": "cy", "term": "似此星辰非昨夜，为谁风露立中宵", "chars": 14, "pinyin": "", "source": "黄景仁《绮怀》", "meaning": "**还是这样的星辰，却已不是昨夜。为谁在风露中站到半夜？**", "category": "*一、光阴如流水"}, {"id": 115, "collection": "cy", "term": "相见争如不见，有情何似无情", "chars": 12, "pinyin": "", "source": "司马光《西江月》", "meaning": "***见了面倒不如不见，有情倒不如无情。司马光一辈子写史，只写过一首情词，句句是泪。***", "category": "*二、情深缘浅"}, {"id": 116, "collection": "cy", "term": "早知如此绊人心，何如当初莫相识", "chars": 14, "pinyin": "", "source": "李白《秋风词》", "meaning": "***早知道相思这样牵绊人心，当初还不如不相识。李白豪放一生，也逃不过一句相思。***", "category": "*二、情深缘浅"}, {"id": 117, "collection": "cy", "term": "天涯地角有穷时，只有相思无尽处", "chars": 14, "pinyin": "", "source": "晏殊《玉楼春》", "meaning": "***天涯地角都有尽头，只有相思没有尽头。晏殊把相思写成了天地间唯一无限的东西。***", "category": "*二、情深缘浅"}, {"id": 118, "collection": "cy", "term": "相思相见知何日，此时此夜难为情", "chars": 14, "pinyin": "", "source": "李白《三五七言》", "meaning": "***想见你却不知道何日能见，此刻此夜，情何以堪。秋风里最孤独的追问。***", "category": "*二、情深缘浅"}, {"id": 119, "collection": "cy", "term": "投我以木桃，报之以琼瑶", "chars": 10, "pinyin": "", "source": "《诗经·卫风·木瓜》", "meaning": "*你送我木桃，我回你美玉。不是礼尚往来，是\"永以为好\"的郑重。*", "category": "*二、情深缘浅"}, {"id": 120, "collection": "cy", "term": "若是前生未有缘，待重结、来生愿", "chars": 13, "pinyin": "", "source": "乐婉《卜算子》", "meaning": "**如果前生没有缘分，那就等到来生再续前缘。宋代歌女的诀别，深情又洒脱。**", "category": "*一、光阴如流水"}, {"id": 121, "collection": "cy", "term": "多情只有春庭月，犹为离人照落花", "chars": 14, "pinyin": "", "source": "张泌《寄人》", "meaning": "***多情的只有庭院里的月亮，还替离别的人照着落花。人去楼空，月仍多情。***", "category": "*二、情深缘浅"}, {"id": 122, "collection": "cy", "term": "百岁之后，归于其居", "chars": 8, "pinyin": "", "source": "《诗经·唐风·葛生》", "meaning": "*百年之后，与你同穴而眠。这是《诗经》里最悲伤的情话——生不能同衾，死也要同穴。*", "category": "*二、情深缘浅"}, {"id": 123, "collection": "cy", "term": "从此无心爱良夜，任他明月下西楼", "chars": 14, "pinyin": "", "source": "李益《写情》", "meaning": "***从此再无心欣赏美好的夜晚，任凭明月在西楼下落去。失约之后，良辰美景都成了讽刺。***", "category": "*二、情深缘浅"}, {"id": 124, "collection": "cy", "term": "当君怀归日，是妾断肠时", "chars": 10, "pinyin": "", "source": "李白《春思》", "meaning": "*你想起回家的时候，正是我肝肠寸断的时候。李白写两地相思，一笔写两边。*", "category": "*二、情深缘浅"}, {"id": 125, "collection": "cy", "term": "郎骑竹马来，绕床弄青梅", "chars": 10, "pinyin": "", "source": "李白《长干行》", "meaning": "*你骑着竹马跑来，绕着井栏追青梅玩。青梅竹马，两小无猜，中国人最甜的童年情话。*", "category": "*二、情深缘浅"}, {"id": 126, "collection": "cy", "term": "春风不相识，何事入罗帏", "chars": 10, "pinyin": "", "source": "李白《春思》", "meaning": "*春风啊，我跟你又不认识，为什么吹进我的罗帐？闺中少妇的娇嗔与思念，一起写了。*", "category": "*二、情深缘浅"}, {"id": 127, "collection": "cy", "term": "还君明珠双泪垂，恨不相逢未嫁时", "chars": 14, "pinyin": "", "source": "张籍《节妇吟》", "meaning": "*还给你明珠，眼泪流了下来，只恨没有在嫁人之前遇见你。最无奈的错过。*", "category": "*二、情深缘浅"}, {"id": 128, "collection": "cy", "term": "此情可待成追忆，只是当时已惘然", "chars": 14, "pinyin": "", "source": "李商隐《锦瑟》", "meaning": "*这份情要等到回忆时才懂，可当时只觉得惘然。李商隐说：爱总是在失去后才被看清。*", "category": "*二、情深缘浅"}, {"id": 129, "collection": "cy", "term": "蓬山此去无多路，青鸟殷勤为探看", "chars": 14, "pinyin": "", "source": "李商隐《无题》", "meaning": "*蓬莱山离这里没有多远，青鸟啊，替我殷勤地去看她吧。李商隐把思念托付给神鸟。*", "category": "*二、情深缘浅"}, {"id": 130, "collection": "cy", "term": "月出皎兮，佼人僚兮", "chars": 8, "pinyin": "", "source": "《诗经·陈风·月出》", "meaning": "**月亮出来皎洁明亮，那美人儿多漂亮。三千年前的月光，照见三千年前的思念。**", "category": "*一、光阴如流水"}, {"id": 131, "collection": "cy", "term": "直道相思了无益，未妨惆怅是清狂", "chars": 14, "pinyin": "", "source": "李商隐《无题》", "meaning": "*明知相思没有用，可我还是为你惆怅，算是痴狂。李商隐说：爱一个人，不需要理由。*", "category": "*二、情深缘浅"}, {"id": 132, "collection": "cy", "term": "春心莫共花争发，一寸相思一寸灰", "chars": 14, "pinyin": "", "source": "李商隐《无题》", "meaning": "*春心啊，别和春花一起萌发，一寸相思，就是一寸灰烬。李商隐把相思写成了焚毁。*", "category": "*二、情深缘浅"}, {"id": 133, "collection": "cy", "term": "两鬓可怜青，只为相思老", "chars": 10, "pinyin": "", "source": "晏几道《生查子》", "meaning": "**两鬓本是一头青丝，只因相思才变老。**", "category": "*一、光阴如流水"}, {"id": 134, "collection": "cy", "term": "花自飘零水自流。一种相思，两处闲愁", "chars": 15, "pinyin": "", "source": "李清照《一剪梅》", "meaning": "*花自己飘落，水自己流走。同一种相思，牵动两处闲愁。李清照把两地相思写得通透。*", "category": "*二、情深缘浅"}, {"id": 135, "collection": "cy", "term": "此情无计可消除，才下眉头，却上心头", "chars": 15, "pinyin": "", "source": "李清照《一剪梅》", "meaning": "*这份情怎么都排解不掉，刚下了眉头，又上了心头。李清照写相思，写到了身体的每一处。*", "category": "*二、情深缘浅"}, {"id": 136, "collection": "cy", "term": "和羞走，倚门回首，却把青梅嗅", "chars": 12, "pinyin": "", "source": "李清照《点绛唇》", "meaning": "*含羞跑开，却又倚着门回头，假装去嗅那枝青梅。少女怀春的娇态，被李清照写绝了。*", "category": "*二、情深缘浅"}, {"id": 137, "collection": "cy", "term": "生怕离怀别苦，多少事、欲说还休", "chars": 13, "pinyin": "", "source": "李清照《凤凰台上忆吹箫》", "meaning": "*最怕离别之苦，多少心事，想说又停住。李清照把欲言又止的离别写绝了。*", "category": "*二、情深缘浅"}, {"id": 138, "collection": "cy", "term": "新来瘦，非干病酒，不是悲秋", "chars": 11, "pinyin": "", "source": "李清照《凤凰台上忆吹箫》", "meaning": "*近来瘦了，不是因为喝酒，也不是因为悲秋——是因为想你。李清照用排除法说相思。*", "category": "*二、情深缘浅"}, {"id": 139, "collection": "cy", "term": "系我一生心，负你千行泪", "chars": 10, "pinyin": "", "source": "柳永《忆帝京》", "meaning": "**把我一生的心都系在你身上，却辜负了你千行泪。柳永写离别后的愧疚与深情。**", "category": "*一、光阴如流水"}, {"id": 140, "collection": "cy", "term": "寻寻觅觅，冷冷清清，凄凄惨惨戚戚", "chars": 14, "pinyin": "", "source": "李清照《声声慢》", "meaning": "*寻寻觅觅，冷冷清清，凄凄惨惨戚戚。十四个叠字，写尽了孤独的层次。*", "category": "*二、情深缘浅"}, {"id": 141, "collection": "cy", "term": "泪眼问花花不语，乱红飞过秋千去", "chars": 14, "pinyin": "", "source": "欧阳修《蝶恋花》", "meaning": "*含泪问花，花不说话，只有花瓣飞过秋千。欧阳修写闺怨，怨到花都不理她。*", "category": "*二、情深缘浅"}, {"id": 142, "collection": "cy", "term": "人生自是有情痴，此恨不关风与月", "chars": 14, "pinyin": "", "source": "欧阳修《玉楼春》", "meaning": "*人生来就是痴情人，这份恨与风月无关。欧阳修说：痴情是天性，不是风景惹的祸。*", "category": "*二、情深缘浅"}, {"id": 143, "collection": "cy", "term": "离愁渐远渐无穷，迢迢不断如春水", "chars": 14, "pinyin": "", "source": "欧阳修《玉楼春》", "meaning": "*离愁越走越远越无穷，绵绵不断像春水。欧阳修把愁写成了流不尽的河。*", "category": "*二、情深缘浅"}, {"id": 144, "collection": "cy", "term": "人生何处不相逢", "chars": 7, "pinyin": "", "source": "晏殊《金柅园》", "meaning": "*一曲清歌满樽酒，人生何处不相逢。天涯海角，总有再见的一天——晏殊把离别写出了底气。*", "category": "*二、情深缘浅"}, {"id": 145, "collection": "cy", "term": "明月楼高休独倚，酒入愁肠，化作相思泪", "chars": 16, "pinyin": "", "source": "范仲淹《苏幕遮》", "meaning": "*明月高楼别独自倚靠，酒进了愁肠，都化作了相思的眼泪。范仲淹写相思，铁汉也柔情。*", "category": "*二、情深缘浅"}, {"id": 146, "collection": "cy", "term": "碧云天，黄叶地，秋色连波，波上寒烟翠", "chars": 15, "pinyin": "", "source": "范仲淹《苏幕遮》", "meaning": "*碧空如洗，黄叶满地，秋色连着水波，水波上浮着翠烟。写秋色之美，这是第一名。*", "category": "*二、情深缘浅"}, {"id": 147, "collection": "cy", "term": "千里孤坟，无处话凄凉", "chars": 9, "pinyin": "", "source": "苏轼《江城子·乙卯正月二十日夜记梦》", "meaning": "*千里之外的孤坟，想说句话都无处可说。苏轼悼念亡妻，一开口就是十年的凄凉。*", "category": "*二、情深缘浅"}, {"id": 148, "collection": "cy", "term": "执子之手，与子偕老", "chars": 8, "pinyin": "", "source": "《诗经·邶风·击鼓》", "meaning": "*牵着你的手，一起慢慢变老。没有一句甜言蜜语，却是中国人心中最重的誓言。*", "category": "*二、情深缘浅"}, {"id": 149, "collection": "cy", "term": "愿我如星君如月，夜夜流光相皎洁", "chars": 14, "pinyin": "", "source": "范成大《车遥遥篇》", "meaning": "*愿我是星星你是月亮，夜夜一起发光，交相辉映。范成大把相守写成了天文现象。*", "category": "*二、情深缘浅"}, {"id": 150, "collection": "cy", "term": "君当作磐石，妾当作蒲苇", "chars": 10, "pinyin": "", "source": "《孔雀东南飞》", "meaning": "***你该做磐石，我做蒲苇。磐石不移，蒲苇不断，这是刘兰芝对爱情最硬的誓言。***", "category": "*二、情深缘浅"}, {"id": 151, "collection": "cy", "term": "此去经年，应是良辰好景虚设", "chars": 12, "pinyin": "", "source": "柳永《雨霖铃》", "meaning": "*你走了之后，再好的时光，也都是虚设。*", "category": "*二、情深缘浅"}, {"id": 152, "collection": "cy", "term": "莫逆之交", "chars": 4, "pinyin": "", "source": "《庄子·大宗师》", "meaning": "*心意相通，没有违逆。庄子说，这样的朋友，可以托付生死。*", "category": "*二、情深缘浅"}, {"id": 153, "collection": "cy", "term": "劝君更尽一杯酒，西出阳关无故人", "chars": 14, "pinyin": "", "source": "王维《送元二使安西》", "meaning": "*再喝一杯吧，出了阳关，就再也没有老朋友了。这一杯，喝了一千年。*", "category": "*二、情深缘浅"}, {"id": 154, "collection": "cy", "term": "春风又绿江南岸，明月何时照我还", "chars": 14, "pinyin": "", "source": "王安石《泊船瓜洲》", "meaning": "*春天又绿了江南，明月啊，你什么时候照我回家？*", "category": "*二、情深缘浅"}, {"id": 155, "collection": "cy", "term": "山回路转不见君，雪上空留马行处", "chars": 14, "pinyin": "", "source": "岑参《白雪歌送武判官归京》", "meaning": "*人走远了，山路拐弯看不见了，雪地上只剩下一行马蹄印。送别的尽头，是无声的凝望。*", "category": "*二、情深缘浅"}, {"id": 156, "collection": "cy", "term": "海内存知己，天涯若比邻", "chars": 10, "pinyin": "", "source": "王勃《送杜少府之任蜀州》", "meaning": "*四海之内都有知心人，就算在天涯，也像邻居一样近。千古送别第一句。*", "category": "*二、情深缘浅"}, {"id": 157, "collection": "cy", "term": "故人入我梦，明我长相忆", "chars": 10, "pinyin": "", "source": "杜甫《梦李白》", "meaning": "***老朋友来到我的梦里，是因为知道我长久地想念你。杜甫梦李白，梦的是生死之交。***", "category": "*二、情深缘浅"}, {"id": 158, "collection": "cy", "term": "人生不相见，动如参与商", "chars": 10, "pinyin": "", "source": "杜甫《赠卫八处士》", "meaning": "***人生在世，老朋友常难得一见，像参星与商星，此出彼没。***", "category": "*二、情深缘浅"}, {"id": 159, "collection": "cy", "term": "管鲍之交", "chars": 4, "pinyin": "", "source": "《史记·管晏列传》", "meaning": "*管仲和鲍叔牙，你懂我的贪，我懂你的能。一辈子的知己，莫过于此。*", "category": "*二、情深缘浅"}, {"id": 160, "collection": "cy", "term": "洛阳亲友如相问，一片冰心在玉壶", "chars": 14, "pinyin": "", "source": "王昌龄《芙蓉楼送辛渐》", "meaning": "*家乡的亲友如果问起我，就说我的心像玉壶里的冰一样清澈。*", "category": "*二、情深缘浅"}, {"id": 161, "collection": "cy", "term": "高山流水", "chars": 4, "pinyin": "", "source": "《列子·汤问》", "meaning": "*伯牙鼓琴，钟子期听得出高山，听得出流水。子期死，伯牙摔琴绝弦。知音，一个就够。*", "category": "*二、情深缘浅"}, {"id": 162, "collection": "cy", "term": "知音少，弦断有谁听", "chars": 8, "pinyin": "", "source": "岳飞《小重山》", "meaning": "***知音太少，琴弦弹断了又有谁听？岳飞报国无门，只能把心事说给琴听。***", "category": "*二、情深缘浅"}, {"id": 163, "collection": "cy", "term": "倚门倚闾", "chars": 4, "pinyin": "", "source": "《战国策·齐策六》", "meaning": "*母亲靠着门框，望着巷口，等孩子白回家。天下的父母，都这样等过。*", "category": "*二、情深缘浅"}, {"id": 164, "collection": "cy", "term": "相逢意气为君饮，系马高楼垂柳边", "chars": 14, "pinyin": "", "source": "王维《少年行》", "meaning": "**相逢意气相投，就为你痛饮；把马系在高楼边的垂柳下。少年侠客的豪情。**", "category": "*一、光阴如流水"}, {"id": 165, "collection": "cy", "term": "投分寄石友，白首同所归", "chars": 10, "pinyin": "", "source": "潘岳《金谷集作诗》", "meaning": "**你我情投意合，托命于金石之交，到白头也一同归去。**", "category": "*一、光阴如流水"}, {"id": 166, "collection": "cy", "term": "莫愁前路无知己，天下谁人不识君", "chars": 14, "pinyin": "", "source": "高适《别董大》", "meaning": "*别怕前路没有朋友，天底下谁不认识你呢？这是对落魄朋友最大的底气。*", "category": "*二、情深缘浅"}, {"id": 167, "collection": "cy", "term": "无为在歧路，儿女共沾巾", "chars": 10, "pinyin": "", "source": "王勃《送杜少府之任蜀州》", "meaning": "*别在分岔路口，像小儿女一样哭哭啼啼。洒脱，是古人送别的体面。*", "category": "*二、情深缘浅"}, {"id": 168, "collection": "cy", "term": "同是天涯沦落人，相逢何必曾相识", "chars": 14, "pinyin": "", "source": "白居易《琵琶行》", "meaning": "*都是漂泊天涯的失意人，相逢何必非要认识。陌生人的共鸣，最动人。*", "category": "*二、情深缘浅"}, {"id": 169, "collection": "cy", "term": "长亭外，古道边，芳草碧连天", "chars": 11, "pinyin": "", "source": "李叔同《送别》", "meaning": "*晚风拂柳笛声残，夕阳山外山。一首《送别》，送走了多少代人的青春。*", "category": "*二、情深缘浅"}, {"id": 170, "collection": "cy", "term": "桃花潭水深千尺，不及汪伦送我情", "chars": 14, "pinyin": "", "source": "李白《赠汪伦》", "meaning": "*桃花潭水再深，也深不过汪伦送我的一片情。*", "category": "*二、情深缘浅"}, {"id": 171, "collection": "cy", "term": "倾盖如故", "chars": 4, "pinyin": "", "source": "《史记·鲁仲连邹阳列传》", "meaning": "*白头如新，倾盖如故。有人认识一辈子还是陌生人，有人停车交谈一瞬，便是一辈子的朋友。*", "category": "*二、情深缘浅"}, {"id": 172, "collection": "cy", "term": "浮云一别后，流水十年间", "chars": 10, "pinyin": "", "source": "韦应物《淮上喜会梁州故人》", "meaning": "*像浮云一样一别，像流水一样十年。老友重逢，千言万语只化作一杯酒。*", "category": "*二、情深缘浅"}, {"id": 173, "collection": "cy", "term": "晚来天欲雪，能饮一杯无", "chars": 10, "pinyin": "", "source": "白居易《问刘十九》", "meaning": "*天要下雪了，能来喝一杯吗？最好的友情，就是这种随时可以约的酒。*", "category": "*二、情深缘浅"}, {"id": 174, "collection": "cy", "term": "故人具鸡黍，邀我至田家", "chars": 10, "pinyin": "", "source": "孟浩然《过故人庄》", "meaning": "*老朋友备好了鸡和黄米饭，邀我去他家做客。人间至味，是故人炊烟。*", "category": "*二、情深缘浅"}, {"id": 175, "collection": "cy", "term": "我寄愁心与明月，随风直到夜郎西", "chars": 14, "pinyin": "", "source": "李白《闻王昌龄左迁龙标遥有此寄》", "meaning": "***我把忧愁的心托付给明月，随风吹到你贬谪的地方。朋友落难，李白把整颗心寄了出去。***", "category": "*二、情深缘浅"}, {"id": 176, "collection": "cy", "term": "与君歌一曲，请君为我倾耳听", "chars": 12, "pinyin": "", "source": "李白《将进酒》", "meaning": "*为你唱一首歌，请你侧耳倾听。李白劝酒，劝得肝胆相照。*", "category": "*二、情深缘浅"}, {"id": 177, "collection": "cy", "term": "白日放歌须纵酒，青春作伴好还乡", "chars": 14, "pinyin": "", "source": "杜甫《闻官军收河南河北》", "meaning": "*大白天放声高歌，就该纵酒痛饮；趁着青春年华，正好结伴还乡。杜甫一生最快乐的一句。*", "category": "*二、情深缘浅"}, {"id": 178, "collection": "cy", "term": "烽火连三月，家书抵万金", "chars": 10, "pinyin": "", "source": "杜甫《春望》", "meaning": "*战火连绵三个月，一封家书抵得上万两黄金。乱世里，家书就是最贵的东西。*", "category": "*二、情深缘浅"}, {"id": 179, "collection": "cy", "term": "露从今夜白，月是故乡明", "chars": 10, "pinyin": "", "source": "杜甫《月夜忆舍弟》", "meaning": "*从今夜起就是白露节气，月亮还是故乡的最明。杜甫说：不是因为故乡的月亮特别亮，是因为那里有家人。*", "category": "*二、情深缘浅"}, {"id": 180, "collection": "cy", "term": "数声风笛离亭晚，君向潇湘我向秦", "chars": 14, "pinyin": "", "source": "郑谷《淮上与友人别》", "meaning": "***晚亭里几声风笛，你要去潇湘，我要去长安。从此一南一北，各奔天涯。***", "category": "*二、情深缘浅"}, {"id": 181, "collection": "cy", "term": "海上生明月，天涯共此时", "chars": 10, "pinyin": "", "source": "张九龄《望月怀远》", "meaning": "**海上升起明月，天涯各处的人同时仰望。一句诗，连起所有思念。**", "category": "*一、光阴如流水"}, {"id": 182, "collection": "cy", "term": "正是江南好风景，落花时节又逢君", "chars": 14, "pinyin": "", "source": "杜甫《江南逢李龟年》", "meaning": "*江南风景正好，却在落花时节又遇到了你。杜甫和李龟年重逢，重逢在乱世与暮年。*", "category": "*二、情深缘浅"}, {"id": 183, "collection": "cy", "term": "故人西辞黄鹤楼，烟花三月下扬州", "chars": 14, "pinyin": "", "source": "李白《黄鹤楼送孟浩然之广陵》", "meaning": "*老朋友在黄鹤楼和我告别，烟花三月顺流直下去扬州。李白把离别写得风光无限。*", "category": "*二、情深缘浅"}, {"id": 184, "collection": "cy", "term": "请君试问东流水，别意与之谁短长", "chars": 14, "pinyin": "", "source": "李白《金陵酒肆留别》", "meaning": "***请你问问东流的江水，离别的情意和它比，谁更长？***", "category": "*二、情深缘浅"}, {"id": 185, "collection": "cy", "term": "聚散苦匆匆，此恨无穷", "chars": 9, "pinyin": "", "source": "欧阳修《浪淘沙》", "meaning": "***相聚和分离都太匆匆，这遗憾无穷无尽。***", "category": "*二、情深缘浅"}, {"id": 186, "collection": "cy", "term": "黄鹤一去不复返，白云千载空悠悠", "chars": 14, "pinyin": "", "source": "崔颢《黄鹤楼》", "meaning": "*黄鹤一去再不回来，白云千年空空飘荡。崔颢登楼，看见的是时间的空洞。*", "category": "*二、情深缘浅"}, {"id": 187, "collection": "cy", "term": "日暮乡关何处是？烟波江上使人愁", "chars": 14, "pinyin": "", "source": "崔颢《黄鹤楼》", "meaning": "*黄昏了，故乡在哪边？江上烟波浩渺，让人发愁。崔颢把乡愁写成了烟波。*", "category": "*二、情深缘浅"}, {"id": 188, "collection": "cy", "term": "江春不肯留行客，草色青青送马蹄", "chars": 14, "pinyin": "", "source": "刘长卿《送李判官之润州行营》", "meaning": "**江边的春天不肯留客，只有青青草色一路送着马蹄远去。**", "category": "*一、光阴如流水"}, {"id": 189, "collection": "cy", "term": "浮云游子意，落日故人情", "chars": 10, "pinyin": "", "source": "李白《送友人》", "meaning": "*浮云是游子的心意，落日是故人的情谊。李白把离别写成了天边的风景。*", "category": "*二、情深缘浅"}, {"id": 190, "collection": "cy", "term": "奇文共欣赏，疑义相与析", "chars": 10, "pinyin": "", "source": "陶渊明《移居》", "meaning": "**有好文章一起欣赏，有疑难一起分析。朋友相处最高的乐趣。**", "category": "*一、光阴如流水"}, {"id": 191, "collection": "cy", "term": "相逢一醉是前缘", "chars": 7, "pinyin": "", "source": "苏轼《浣溪沙》", "meaning": "***能相逢大醉一场，都是前世修来的缘分。***", "category": "*二、情深缘浅"}, {"id": 192, "collection": "cy", "term": "花间一壶酒，独酌无相亲", "chars": 10, "pinyin": "", "source": "李白《月下独酌》", "meaning": "**花丛间一壶酒，独自饮，没有亲近的人。李白孤独，却孤独得浪漫。**", "category": "*一、光阴如流水"}, {"id": 193, "collection": "cy", "term": "抽刀断水水更流，举杯消愁愁更愁", "chars": 14, "pinyin": "", "source": "李白《宣州谢朓楼饯别校书叔云》", "meaning": "*抽刀断水，水更流；举杯消愁，愁更愁。李白把愁写成了堵不住的河。*", "category": "*二、情深缘浅"}, {"id": 194, "collection": "cy", "term": "欲渡黄河冰塞川，将登太行雪满山", "chars": 14, "pinyin": "", "source": "李白《行路难》", "meaning": "*想渡黄河，冰封住了河；要登太行，雪埋住了山。李白写困境，写得到处碰壁。*", "category": "*二、情深缘浅"}, {"id": 195, "collection": "cy", "term": "大鹏一日同风起，扶摇直上九万里", "chars": 14, "pinyin": "", "source": "李白《上李邕》", "meaning": "*大鹏有一天乘风而起，扶摇直上九万里高空。李白自比大鹏，狂得理直气壮。*", "category": "*二、情深缘浅"}, {"id": 196, "collection": "cy", "term": "仰天大笑出门去，我辈岂是蓬蒿人", "chars": 14, "pinyin": "", "source": "李白《南陵别儿童入京》", "meaning": "*仰天大笑走出门去，我这样的人，怎么会是草野之辈？李白入京时的意气，震得人耳鸣。*", "category": "*二、情深缘浅"}, {"id": 197, "collection": "cy", "term": "蜀道之难，难于上青天", "chars": 9, "pinyin": "", "source": "李白《蜀道难》", "meaning": "*蜀道难走，比登天还难。李白一句感叹，成了千古最难走的路。*", "category": "*二、情深缘浅"}, {"id": 198, "collection": "cy", "term": "一夫当关，万夫莫开", "chars": 8, "pinyin": "", "source": "李白《蜀道难》", "meaning": "*一个人守住关口，一万人也攻不开。李白写剑阁，写成了险要的代名词。*", "category": "*二、情深缘浅"}, {"id": 199, "collection": "cy", "term": "朝辞白帝彩云间，千里江陵一日还", "chars": 14, "pinyin": "", "source": "李白《早发白帝城》", "meaning": "*早晨告别彩云间的白帝城，千里之外的江陵，一天就回来了。李白遇赦东归，快活得像只鸟。*", "category": "*二、情深缘浅"}, {"id": 200, "collection": "cy", "term": "人生贵相知，何必金与钱", "chars": 10, "pinyin": "", "source": "李白《赠友人》", "meaning": "**人生最可贵的是彼此相知，何必在乎金钱。**", "category": "*一、光阴如流水"}, {"id": 201, "collection": "cy", "term": "离多最是，东西流水", "chars": 8, "pinyin": "", "source": "晏几道《清平乐》", "meaning": "**离别最多的，就像东西分流的水。聚少离多，自古皆然。**", "category": "*一、光阴如流水"}, {"id": 202, "collection": "cy", "term": "春风得意马蹄疾，一日看尽长安花", "chars": 14, "pinyin": "", "source": "孟郊《登科后》", "meaning": "*春风得意，马蹄轻快，一天就看尽了长安的花。孟郊考上进士，高兴得看花都嫌慢。*", "category": "*二、情深缘浅"}, {"id": 203, "collection": "cy", "term": "慈母手中线，游子身上衣", "chars": 10, "pinyin": "", "source": "孟郊《游子吟》", "meaning": "*慈母手中的针线，缝成了游子身上的衣裳。天底下最朴素、最伟大的一句母爱。*", "category": "*二、情深缘浅"}, {"id": 204, "collection": "cy", "term": "谁言寸草心，报得三春晖", "chars": 10, "pinyin": "", "source": "孟郊《游子吟》", "meaning": "*谁说小草的寸心，能报答春天的阳光？孟郊说：母亲的爱，儿女永远报不完。*", "category": "*二、情深缘浅"}, {"id": 205, "collection": "cy", "term": "西风多少恨，吹不散眉弯", "chars": 10, "pinyin": "", "source": "纳兰性德《临江仙》", "meaning": "**西风有多少愁恨，也吹不散眉头的皱痕。**", "category": "*一、光阴如流水"}, {"id": 206, "collection": "cy", "term": "相知无远近，万里尚为邻", "chars": 10, "pinyin": "", "source": "张九龄《送韦城李少府》", "meaning": "*相知的人不分远近，相隔万里也像邻居。张九龄说：知己之间，没有距离。*", "category": "*二、情深缘浅"}, {"id": 207, "collection": "cy", "term": "闻道欲来相问讯，西楼望月几回圆", "chars": 14, "pinyin": "", "source": "韦应物《寄李儋元锡》", "meaning": "**听说你要来探望，我在西楼望月亮圆了几回。等友人的心情，写得真真切切。**", "category": "*一、光阴如流水"}, {"id": 208, "collection": "cy", "term": "若到江南赶上春，千万和春住", "chars": 12, "pinyin": "", "source": "王观《卜算子·送鲍浩然之浙东》", "meaning": "*如果到江南赶上了春天，千万要和春天一起住下。王观送别，送出了一整个春天。*", "category": "*二、情深缘浅"}, {"id": 209, "collection": "cy", "term": "寂寞离亭掩，江山此夜寒", "chars": 10, "pinyin": "", "source": "王勃《江亭夜月送别》", "meaning": "**离亭冷冷地关上了门，这一夜江山都显得寒冷。送别后的孤寂，八个字写尽。**", "category": "*一、光阴如流水"}, {"id": 210, "collection": "cy", "term": "梧桐叶上三更雨，叶叶声声是别离", "chars": 14, "pinyin": "", "source": "周紫芝《鹧鸪天》", "meaning": "**梧桐叶上的三更雨，叶叶声声都是别离。**", "category": "*一、光阴如流水"}, {"id": 211, "collection": "cy", "term": "落地为兄弟，何必骨肉亲", "chars": 10, "pinyin": "", "source": "陶渊明《杂诗》", "meaning": "*四海之内都是兄弟，何必非要骨肉至亲？陶渊明把天下人写成了家人。*", "category": "*二、情深缘浅"}, {"id": 212, "collection": "cy", "term": "衣不如新，人不如故", "chars": 8, "pinyin": "", "source": "《古艳歌》", "meaning": "***衣服是新的好，人却是旧的好。老朋友的珍贵，古人早就说透。***", "category": "*二、情深缘浅"}, {"id": 213, "collection": "cy", "term": "四海之内皆兄弟", "chars": 7, "pinyin": "", "source": "《论语·颜渊》", "meaning": "**天下的人都可以做兄弟。子夏说：只要君子敬而无失，四海之内皆兄弟。**", "category": "*一、光阴如流水"}, {"id": 214, "collection": "cy", "term": "山河不足重，重在遇知己", "chars": 10, "pinyin": "", "source": "鲍溶《壮士行》", "meaning": "***山河不值得看重，重要的是遇到知己。***", "category": "*二、情深缘浅"}, {"id": 215, "collection": "cy", "term": "刎颈之交", "chars": 4, "pinyin": "", "source": "《史记·廉颇蔺相如列传》", "meaning": "***生死之交。廉颇与蔺相如从仇敌到刎颈之交，成了友谊的巅峰。***", "category": "*二、情深缘浅"}, {"id": 216, "collection": "cy", "term": "忘年之交", "chars": 4, "pinyin": "", "source": "《后汉书·祢衡传》", "meaning": "***年龄差距很大却结为知己。孔融与祢衡，一个四十一个二十，成了忘年交。***", "category": "*二、情深缘浅"}, {"id": 217, "collection": "cy", "term": "士为知己者死", "chars": 6, "pinyin": "", "source": "《战国策·赵策一》", "meaning": "***士人愿为懂得自己的人献出生命。豫让漆身吞炭为智伯报仇，践行了这句话。***", "category": "*二、情深缘浅"}, {"id": 218, "collection": "cy", "term": "管宁割席", "chars": 4, "pinyin": "", "source": "《世说新语·德行》", "meaning": "***管宁与华歆同席读书，见华歆贪慕富贵，便割席分坐：你不是我的朋友。*** **********", "category": "*二、情深缘浅"}, {"id": 219, "collection": "cy", "term": "友直，友谅，友多闻，益矣", "chars": 9, "pinyin": "", "source": "《论语·季氏》", "meaning": "**朋友正直、诚信、见多识广，是有益的。孔子的择友标准，至今适用。**", "category": "*一、光阴如流水"}, {"id": 220, "collection": "cy", "term": "各在天一涯，道路阻且长", "chars": 10, "pinyin": "", "source": "《古诗十九首·行行重行行》", "meaning": "*你我各在天的一方，道路又远又难走。古诗十九首把离别写成了天涯。* *******", "category": "*二、情深缘浅"}, {"id": 221, "collection": "cy", "term": "三夜频梦君，情亲见君意", "chars": 10, "pinyin": "", "source": "杜甫《梦李白二首》", "meaning": "**一连三夜梦到你，情谊之深可见你对我的真心。杜甫梦见李白，醒来写诗相寄。**", "category": "*一、光阴如流水"}, {"id": 222, "collection": "cy", "term": "人生飘忽百年内，且须酣畅万古情", "chars": 14, "pinyin": "", "source": "李白《答王十二寒夜独酌有怀》", "meaning": "**人生百年，飘忽不定，就该痛痛快快喝一场，酣畅这万古豪情。**", "category": "*一、光阴如流水"}, {"id": 223, "collection": "cy", "term": "王孙游兮不归，春草生兮萋萋", "chars": 12, "pinyin": "", "source": "《楚辞·招隐士》", "meaning": "**王孙出游不归，春草已经长得茂盛。等不到人，就看春草一年年绿。**", "category": "*一、光阴如流水"}, {"id": 224, "collection": "cy", "term": "醉别西楼醒不记，春梦秋云，聚散真容易", "chars": 16, "pinyin": "", "source": "晏几道《蝶恋花》", "meaning": "**醉中告别西楼，醒来都不记得了。春梦秋云，聚散真容易。**", "category": "*一、光阴如流水"}, {"id": 225, "collection": "cy", "term": "仍怜故乡水，万里送行舟", "chars": 10, "pinyin": "", "source": "李白《渡荆门送别》", "meaning": "***还是故乡的水最深情，一路送我行了万里。离别时最舍不得的，是故乡。***", "category": "*二、情深缘浅"}, {"id": 226, "collection": "cy", "term": "孤帆远影碧空尽，唯见长江天际流", "chars": 14, "pinyin": "", "source": "李白《黄鹤楼送孟浩然之广陵》", "meaning": "*船影消失在碧空尽头，只剩下长江流向天边。目送，是最深的深情。*", "category": "*二、情深缘浅"}, {"id": 227, "collection": "cy", "term": "水木清华", "chars": 4, "pinyin": "", "source": "谢混《游西池》", "meaning": "*水清木华，池馆清幽。清华大学的校名，就出自这里。*", "category": "*二、情深缘浅"}, {"id": 228, "collection": "cy", "term": "明月松间照，清泉石上流", "chars": 10, "pinyin": "", "source": "王维《山居秋暝》", "meaning": "*月光穿过松林，清泉流过石上。空山新雨后，这是中国人理想中最高级的安静。*", "category": "*二、情深缘浅"}, {"id": 229, "collection": "cy", "term": "江流天地外，山色有无中", "chars": 10, "pinyin": "", "source": "王维《汉江临泛》", "meaning": "*江水好像流到天地之外，山色在若有若无之间。水墨画的最高境界，不过如此。*", "category": "*二、情深缘浅"}, {"id": 230, "collection": "cy", "term": "两个黄鹂鸣翠柳，一行白鹭上青天", "chars": 14, "pinyin": "", "source": "杜甫《绝句》", "meaning": "*黄鹂翠柳，白鹭青天。四个颜色，一幅画。杜甫用二十个字，画了四扇窗。*", "category": "*二、情深缘浅"}, {"id": 231, "collection": "cy", "term": "一道残阳铺水中，半江瑟瑟半江红", "chars": 14, "pinyin": "", "source": "白居易《暮江吟》", "meaning": "*夕阳铺在水面上，江水一半碧绿一半红。夕阳下最温柔的定格。*", "category": "*二、情深缘浅"}, {"id": 232, "collection": "cy", "term": "碧海青天", "chars": 4, "pinyin": "", "source": "李商隐《嫦娥》", "meaning": "*嫦娥应悔偷灵药，碧海青天夜夜心。一个人守着整片夜空，是嫦娥，也是每一个孤独的人。*", "category": "*二、情深缘浅"}, {"id": 233, "collection": "cy", "term": "余霞成绮", "chars": 4, "pinyin": "", "source": "谢朓《晚登三山还望京邑》", "meaning": "*余霞散成绮，澄江静如练。晚霞像绸缎铺开，江水像白练静卧。*", "category": "*二、情深缘浅"}, {"id": 234, "collection": "cy", "term": "潮平两岸阔，风正一帆悬", "chars": 10, "pinyin": "", "source": "王湾《次北固山下》", "meaning": "*潮水涨平，两岸开阔；风顺，帆正好。人生顺遂时，就该是这样。*", "category": "*二、情深缘浅"}, {"id": 235, "collection": "cy", "term": "千山鸟飞绝，万径人踪灭", "chars": 10, "pinyin": "", "source": "柳宗元《江雪》", "meaning": "***千座山看不到鸟影，万条路不见人踪。天地一片洁白，孤独到了极致。***", "category": "*二、情深缘浅"}, {"id": 236, "collection": "cy", "term": "停车坐爱枫林晚，霜叶红于二月花", "chars": 14, "pinyin": "", "source": "杜牧《山行》", "meaning": "*停下马车，是因为喜欢这傍晚的枫林——经霜的枫叶，比二月的花还红。*", "category": "*二、情深缘浅"}, {"id": 237, "collection": "cy", "term": "野火烧不尽，春风吹又生", "chars": 10, "pinyin": "", "source": "白居易《赋得古原草送别》", "meaning": "***野火烧不尽，春风吹又生。草的顽强，就是生命最朴素的力量。***", "category": "*二、情深缘浅"}, {"id": 238, "collection": "cy", "term": "天街小雨润如酥，草色遥看近却无", "chars": 14, "pinyin": "", "source": "韩愈《早春呈水部张十八员外》", "meaning": "*初春的雨像酥油一样润，草色远看有、近看无。最细腻的春天，被韩愈抓住了。*", "category": "*二、情深缘浅"}, {"id": 239, "collection": "cy", "term": "气蒸云梦泽，波撼岳阳城", "chars": 10, "pinyin": "", "source": "孟浩然《望洞庭湖赠张丞相》", "meaning": "***水气蒸腾笼罩云梦泽，波涛撼动岳阳城。写洞庭湖的气势，这两句第一。***", "category": "*二、情深缘浅"}, {"id": 240, "collection": "cy", "term": "忽如一夜春风来，千树万树梨花开", "chars": 14, "pinyin": "", "source": "岑参《白雪歌送武判官归京》", "meaning": "*一夜之间，仿佛春风吹来，千万棵树开满了梨花。把雪写得这么美，只有岑参。*", "category": "*二、情深缘浅"}, {"id": 241, "collection": "cy", "term": "黄河远上白云间，一片孤城万仞山", "chars": 14, "pinyin": "", "source": "王之涣《凉州词》", "meaning": "*黄河一直延伸到白云之间，孤城坐落在万仞高山之下。苍凉得荡气回肠。*", "category": "*二、情深缘浅"}, {"id": 242, "collection": "cy", "term": "溪云初起日沉阁，山雨欲来风满楼", "chars": 14, "pinyin": "", "source": "许浑《咸阳城东楼》", "meaning": "**溪云升起，夕阳沉阁，山雨将来，满楼是风。写景名句，也成了大事将临的预言。**", "category": "*一、光阴如流水"}, {"id": 243, "collection": "cy", "term": "大漠孤烟直，长河落日圆", "chars": 10, "pinyin": "", "source": "王维《使至塞上》", "meaning": "*大漠里一缕孤烟笔直升起，黄河上落日又大又圆。一句话，画出了整个边塞。*", "category": "*二、情深缘浅"}, {"id": 244, "collection": "cy", "term": "山重水复疑无路，柳暗花明又一村", "chars": 14, "pinyin": "", "source": "陆游《游山西村》", "meaning": "*山重水绕，以为没路了；转过弯，柳暗花明，又是一个村庄。绝处逢生，中国人最爱的转机。*", "category": "*二、情深缘浅"}, {"id": 245, "collection": "cy", "term": "星垂平野阔，月涌大江流", "chars": 10, "pinyin": "", "source": "杜甫《旅夜书怀》", "meaning": "*星星垂在辽阔的原野上，月光随着大江奔涌。天地越大，人越渺小。*", "category": "*二、情深缘浅"}, {"id": 246, "collection": "cy", "term": "晨钟暮鼓", "chars": 4, "pinyin": "", "source": "李咸用《山中》", "meaning": "*清晨敲钟，傍晚击鼓。寺院的一天，也是修行的一生。*", "category": "*二、情深缘浅"}, {"id": 247, "collection": "cy", "term": "飞流直下三千尺，疑是银河落九天", "chars": 14, "pinyin": "", "source": "李白《望庐山瀑布》", "meaning": "*三千尺的瀑布直落而下，像银河从九天坠落。李白的想象力，就是天上地下。*", "category": "*二、情深缘浅"}, {"id": 248, "collection": "cy", "term": "落霞与孤鹜齐飞，秋水共长天一色", "chars": 14, "pinyin": "", "source": "王勃《滕王阁序》", "meaning": "*晚霞和孤雁一起飞，秋水和天空一个颜色。千古写景第一名。*", "category": "*二、情深缘浅"}, {"id": 249, "collection": "cy", "term": "山外青山楼外楼，西湖歌舞几时休", "chars": 14, "pinyin": "", "source": "林升《题临安邸》", "meaning": "**山外有山，楼外有楼，西湖边的歌舞何时才停？表面写景，实为忧国。**", "category": "*一、光阴如流水"}, {"id": 250, "collection": "cy", "term": "杏花春雨", "chars": 4, "pinyin": "", "source": "虞集《风入松》", "meaning": "*杏花春雨江南。六个字，就是整个江南的温柔。*", "category": "*二、情深缘浅"}, {"id": 251, "collection": "cy", "term": "空山新雨后，天气晚来秋", "chars": 10, "pinyin": "", "source": "王维《山居秋暝》", "meaning": "*雨后的空山，傍晚的秋凉。王维一开口，就把秋天写在了空气里。*", "category": "*二、情深缘浅"}, {"id": 252, "collection": "cy", "term": "两岸青山相对出，孤帆一片日边来", "chars": 14, "pinyin": "", "source": "李白《望天门山》", "meaning": "***两岸青山迎面耸立，一叶孤帆从日边驶来。李白把船行写成了画卷展开。***", "category": "*二、情深缘浅"}, {"id": 253, "collection": "cy", "term": "大漠沙如雪，燕山月似钩", "chars": 10, "pinyin": "", "source": "李贺《马诗》", "meaning": "**大漠的沙像雪，燕山的月像钩。两句写出边塞的苍凉，也写出建功的渴望。**", "category": "*一、光阴如流水"}, {"id": 254, "collection": "cy", "term": "月落乌啼霜满天，江枫渔火对愁眠", "chars": 14, "pinyin": "", "source": "张继《枫桥夜泊》", "meaning": "***月落乌啼，霜满天地，江枫渔火陪着愁眠的旅人。一首诗，写尽羁旅之夜。***", "category": "*二、情深缘浅"}, {"id": 255, "collection": "cy", "term": "独坐幽篁里，弹琴复长啸", "chars": 10, "pinyin": "", "source": "王维《竹里馆》", "meaning": "**独自坐在幽深的竹林里，弹琴又长啸。王维的孤独，是禅意。**", "category": "*一、光阴如流水"}, {"id": 256, "collection": "cy", "term": "人闲桂花落，夜静春山空", "chars": 10, "pinyin": "", "source": "王维《鸟鸣涧》", "meaning": "*人闲下来，桂花才落；夜静下来，春山才空。王维把安静写成了能听见的声音。*", "category": "*二、情深缘浅"}, {"id": 257, "collection": "cy", "term": "月出惊山鸟，时鸣春涧中", "chars": 10, "pinyin": "", "source": "王维《鸟鸣涧》", "meaning": "*月亮出来惊动了山鸟，偶尔在山涧中鸣叫。以动写静，千古一绝。*", "category": "*二、情深缘浅"}, {"id": 258, "collection": "cy", "term": "空山不见人，但闻人语响", "chars": 10, "pinyin": "", "source": "王维《鹿柴》", "meaning": "*空山里看不见人，只听见说话的声音。王维写幽深，写出了有人的寂静。*", "category": "*二、情深缘浅"}, {"id": 259, "collection": "cy", "term": "返景入深林，复照青苔上", "chars": 10, "pinyin": "", "source": "王维《鹿柴》", "meaning": "*落日余晖照进深林，又照在青苔上。一束光，让深山有了温度。*", "category": "*二、情深缘浅"}, {"id": 260, "collection": "cy", "term": "小楼一夜听春雨，深巷明朝卖杏花", "chars": 14, "pinyin": "", "source": "陆游《临安春雨初霁》", "meaning": "**小楼里听了一夜春雨，明天深巷里就有人卖杏花。春天的消息，最先在巷口。**", "category": "*一、光阴如流水"}, {"id": 261, "collection": "cy", "term": "千里莺啼绿映红，水村山郭酒旗风", "chars": 14, "pinyin": "", "source": "杜牧《江南春》", "meaning": "***千里江南，莺啼绿红相映，水村山郭酒旗招展。***", "category": "*二、情深缘浅"}, {"id": 262, "collection": "cy", "term": "江雨霏霏江草齐，六朝如梦鸟空啼", "chars": 14, "pinyin": "", "source": "韦庄《台城》", "meaning": "**江雨蒙蒙，江草齐整，六朝繁华如梦，只剩鸟在空啼。**", "category": "*一、光阴如流水"}, {"id": 263, "collection": "cy", "term": "杨花榆荚无才思，惟解漫天作雪飞", "chars": 14, "pinyin": "", "source": "韩愈《晚春》", "meaning": "**杨花榆荚没有才气，只知道漫天飞舞像雪。晚春的生机，笨拙也可爱。**", "category": "*一、光阴如流水"}, {"id": 264, "collection": "cy", "term": "杨柳青青江水平，闻郎江上唱歌声", "chars": 14, "pinyin": "", "source": "刘禹锡《竹枝词》", "meaning": "**杨柳青青，江水平平，听见情郎在江上唱歌。民歌风味，清新动人。**", "category": "*一、光阴如流水"}, {"id": 265, "collection": "cy", "term": "树树皆秋色，山山唯落晖", "chars": 10, "pinyin": "", "source": "王绩《野望》", "meaning": "**每棵树都染上秋色，每座山都披着落日余晖。**", "category": "*一、光阴如流水"}, {"id": 266, "collection": "cy", "term": "荷叶罗裙一色裁，芙蓉向脸两边开", "chars": 14, "pinyin": "", "source": "王昌龄《采莲曲》", "meaning": "**荷叶与罗裙一个颜色，荷花在脸庞两边盛开。采莲女与荷花融为一体。**", "category": "*一、光阴如流水"}, {"id": 267, "collection": "cy", "term": "冰雪林中著此身，不同桃李混芳尘", "chars": 14, "pinyin": "", "source": "王冕《白梅》", "meaning": "**白梅在冰雪林中安身，不与桃李混同于世俗尘泥。**", "category": "*一、光阴如流水"}, {"id": 268, "collection": "cy", "term": "乱花渐欲迷人眼，浅草才能没马蹄", "chars": 14, "pinyin": "", "source": "白居易《钱塘湖春行》", "meaning": "*乱花渐要迷住人眼，浅草刚好没过马蹄。白居易写春游，写出了骑马的惬意。*", "category": "*二、情深缘浅"}, {"id": 269, "collection": "cy", "term": "闻道梅花坼晓风，雪堆遍满四山中", "chars": 14, "pinyin": "", "source": "陆游《梅花绝句》", "meaning": "**听说梅花在晓风中绽放，像雪堆一样开满四座山。陆游爱梅，爱到想化身梅花。**", "category": "*一、光阴如流水"}, {"id": 270, "collection": "cy", "term": "接天莲叶无穷碧，映日荷花别样红", "chars": 14, "pinyin": "", "source": "杨万里《晓出净慈寺送林子方》", "meaning": "*荷叶接天，无穷碧绿；荷花映日，别样鲜红。杨万里写西湖六月，写出了颜色的盛宴。*", "category": "*二、情深缘浅"}, {"id": 271, "collection": "cy", "term": "小荷才露尖尖角，早有蜻蜓立上头", "chars": 14, "pinyin": "", "source": "杨万里《小池》", "meaning": "*小荷刚露出尖尖的角，早有蜻蜓停在上面。初夏的生机，小得刚刚好。*", "category": "*二、情深缘浅"}, {"id": 272, "collection": "cy", "term": "儿童急走追黄蝶，飞入菜花无处寻", "chars": 14, "pinyin": "", "source": "杨万里《宿新市徐公店》", "meaning": "*孩子跑着追黄蝴蝶，蝴蝶飞进菜花里就找不到了。杨万里写童趣，写到了人的心里。*", "category": "*二、情深缘浅"}, {"id": 273, "collection": "cy", "term": "墙角数枝梅，凌寒独自开", "chars": 10, "pinyin": "", "source": "王安石《梅花》", "meaning": "***墙角几枝梅花，迎着严寒独自开放。***", "category": "*二、情深缘浅"}, {"id": 274, "collection": "cy", "term": "清水出芙蓉，天然去雕饰", "chars": 10, "pinyin": "", "source": "李白《经乱离后天恩流夜郎忆旧游书怀赠江夏韦太守良宰》", "meaning": "**像清水里长出的芙蓉，天然得不加雕饰。夸人诗文自然，也夸人本性纯真。**", "category": "*一、光阴如流水"}, {"id": 275, "collection": "cy", "term": "迟日江山丽，春风花草香", "chars": 10, "pinyin": "", "source": "杜甫《绝句二首》", "meaning": "*春日照着江山，美丽明净；春风吹着花草，香气袭人。杜甫写春，写得干干净净。*", "category": "*二、情深缘浅"}, {"id": 276, "collection": "cy", "term": "江碧鸟逾白，山青花欲燃", "chars": 10, "pinyin": "", "source": "杜甫《绝句二首》", "meaning": "*江水碧绿，白鸟更白；青山苍翠，红花像要燃烧。杜甫写颜色，写到要烧起来。*", "category": "*二、情深缘浅"}, {"id": 277, "collection": "cy", "term": "随风潜入夜，润物细无声", "chars": 10, "pinyin": "", "source": "杜甫《春夜喜雨》", "meaning": "*春雨随风悄悄落下，润泽万物，细得没有声音。杜甫写雨，写出了温柔。*", "category": "*二、情深缘浅"}, {"id": 278, "collection": "cy", "term": "不是花中偏爱菊，此花开尽更无花", "chars": 14, "pinyin": "", "source": "元稹《菊花》", "meaning": "***不是偏爱菊花，而是菊花谢后，再无花可赏。***", "category": "*二、情深缘浅"}, {"id": 279, "collection": "cy", "term": "窗含西岭千秋雪，门泊东吴万里船", "chars": 14, "pinyin": "", "source": "杜甫《绝句》", "meaning": "*窗框里嵌着西岭的千年积雪，门前停着东吴的万里行船。杜甫写窗前风景，写出了时空的辽阔。*", "category": "*二、情深缘浅"}, {"id": 280, "collection": "cy", "term": "无边落木萧萧下，不尽长江滚滚来", "chars": 14, "pinyin": "", "source": "杜甫《登高》", "meaning": "*无边无际的落叶萧萧而下，望不到头的长江滚滚而来。杜甫登高，看见了整个秋天。*", "category": "*二、情深缘浅"}, {"id": 281, "collection": "cy", "term": "风急天高猿啸哀，渚清沙白鸟飞回", "chars": 14, "pinyin": "", "source": "杜甫《登高》", "meaning": "*风急天高，猿声凄厉；水清沙白，飞鸟盘旋。杜甫写秋天，一开头就是苍凉。* *******", "category": "*二、情深缘浅"}, {"id": 282, "collection": "cy", "term": "桃之夭夭，灼灼其华", "chars": 8, "pinyin": "", "source": "《诗经·周南·桃夭》", "meaning": "**桃树繁茂，花朵灼灼。新娘像桃花一样明媚，是《诗经》里最美的祝福。**", "category": "*一、光阴如流水"}, {"id": 283, "collection": "cy", "term": "秋阴不散霜飞晚，留得枯荷听雨声", "chars": 14, "pinyin": "", "source": "李商隐《宿骆氏亭寄怀崔雍崔衮》", "meaning": "**秋阴不散，霜来得晚，留几枝枯荷，听雨打在上面的声音。**", "category": "*一、光阴如流水"}, {"id": 284, "collection": "cy", "term": "绝代有佳人，幽居在空谷", "chars": 10, "pinyin": "", "source": "杜甫《佳人》", "meaning": "*绝代的美人，幽居在空谷中。杜甫写佳人，写的是高洁的孤独。*", "category": "*二、情深缘浅"}, {"id": 285, "collection": "cy", "term": "天寒翠袖薄，日暮倚修竹", "chars": 10, "pinyin": "", "source": "杜甫《佳人》", "meaning": "*天寒了，翠袖单薄；日暮了，倚着修竹。杜甫写佳人，写成了风骨。*", "category": "*二、情深缘浅"}, {"id": 286, "collection": "cy", "term": "绿阴不减来时路，添得黄鹂四五声", "chars": 14, "pinyin": "", "source": "曾几《三衢道中》", "meaning": "**绿荫不输来时的路，又添了几声黄鹂叫。初夏山行的惬意。**", "category": "*一、光阴如流水"}, {"id": 287, "collection": "cy", "term": "西塞山前白鹭飞，桃花流水鳜鱼肥", "chars": 14, "pinyin": "", "source": "张志和《渔歌子》", "meaning": "***西塞山前白鹭飞，桃花流水鳜鱼肥。一幅江南春钓图。***", "category": "*二、情深缘浅"}, {"id": 288, "collection": "cy", "term": "国破山河在，城春草木深", "chars": 10, "pinyin": "", "source": "杜甫《春望》", "meaning": "*国破了，山河还在；城里春天来了，草木深深。杜甫写乱世之春，草木都长得荒凉。*", "category": "*二、情深缘浅"}, {"id": 289, "collection": "cy", "term": "感时花溅泪，恨别鸟惊心", "chars": 10, "pinyin": "", "source": "杜甫《春望》", "meaning": "*感伤时事，花都溅泪；恨别离散，鸟都惊心。杜甫把心情写给了花鸟。*", "category": "*二、情深缘浅"}, {"id": 290, "collection": "cy", "term": "开轩面场圃，把酒话桑麻", "chars": 10, "pinyin": "", "source": "孟浩然《过故人庄》", "meaning": "*打开窗对着场圃，端起酒杯聊桑麻。孟浩然写田园，写的是接地气的快乐。*", "category": "*二、情深缘浅"}, {"id": 291, "collection": "cy", "term": "花开红树乱莺啼，草长平湖白鹭飞", "chars": 14, "pinyin": "", "source": "徐元杰《湖上》", "meaning": "**花开满树，黄莺乱啼；草长平湖，白鹭飞起。春日的湖上生机勃勃。**", "category": "*一、光阴如流水"}, {"id": 292, "collection": "cy", "term": "野旷天低树，江清月近人", "chars": 10, "pinyin": "", "source": "孟浩然《宿建德江》", "meaning": "*原野空旷，天比树还低；江水清澈，月离人很近。孟浩然夜泊，泊出了空明。*", "category": "*二、情深缘浅"}, {"id": 293, "collection": "cy", "term": "横看成岭侧成峰，远近高低各不同", "chars": 14, "pinyin": "", "source": "苏轼《题西林壁》", "meaning": "***横看是岭，侧看是峰，远近高低各不同。看山如此，看事亦然。***", "category": "*二、情深缘浅"}, {"id": 294, "collection": "cy", "term": "细雨斜风作晓寒，淡烟疏柳媚晴滩", "chars": 14, "pinyin": "", "source": "苏轼《浣溪沙》", "meaning": "**细雨斜风带来清晨的寒意，淡烟疏柳点缀晴日河滩。苏轼写早春，清淡有味。**", "category": "*一、光阴如流水"}, {"id": 295, "collection": "cy", "term": "云来山更佳，云去山如画", "chars": 10, "pinyin": "", "source": "张养浩《雁儿落兼得胜令》", "meaning": "***云来时山色更佳，云去时山如画。山因云而变化，静中有动。***", "category": "*二、情深缘浅"}, {"id": 296, "collection": "cy", "term": "清晨入古寺，初日照高林", "chars": 10, "pinyin": "", "source": "常建《题破山寺后禅院》", "meaning": "*清晨走进古寺，初升的太阳照着高高的树林。常建写寺院清晨，写出了通透。*", "category": "*二、情深缘浅"}, {"id": 297, "collection": "cy", "term": "蝉噪林逾静，鸟鸣山更幽", "chars": 10, "pinyin": "", "source": "王籍《入若耶溪》", "meaning": "*蝉叫得越响，林子越显安静；鸟鸣得越欢，山间越显幽深。以动衬静，千古名句。*", "category": "*二、情深缘浅"}, {"id": 298, "collection": "cy", "term": "天苍苍，野茫茫，风吹草低见牛羊", "chars": 13, "pinyin": "", "source": "《敕勒歌》", "meaning": "***天蓝蓝，野茫茫，风吹草低露出成群的牛羊。北方草原的辽阔，尽在这几句。***", "category": "*二、情深缘浅"}, {"id": 299, "collection": "cy", "term": "山中何所有，岭上多白云", "chars": 10, "pinyin": "", "source": "陶弘景《诏问山中何所有赋诗以答》", "meaning": "**山中有什么？只有岭上的白云。陶弘景答皇帝：山中最富，是自由。**", "category": "*一、光阴如流水"}, {"id": 300, "collection": "cy", "term": "空山松子落，幽人应未眠", "chars": 10, "pinyin": "", "source": "韦应物《秋夜寄丘二十二员外》", "meaning": "***空山里松子轻轻落下，远方的你此时应该还未入眠。秋夜的思念，安静得像一粒松子。***", "category": "*二、情深缘浅"}, {"id": 301, "collection": "cy", "term": "捐躯赴国难，视死忽如归", "chars": 10, "pinyin": "", "source": "曹植《白马篇》", "meaning": "*为国难献身，把死亡看作回家。少年英雄的豪气，千年不减。*", "category": "*二、情深缘浅"}, {"id": 302, "collection": "cy", "term": "粉身碎骨浑不怕，要留清白在人间", "chars": 14, "pinyin": "", "source": "于谦《石灰吟》", "meaning": "*粉身碎骨都不怕，只要把清白留在人间。于谦写的是石灰，也是自己。*", "category": "*二、情深缘浅"}, {"id": 303, "collection": "cy", "term": "先天下之忧而忧，后天下之乐而乐", "chars": 14, "pinyin": "", "source": "范仲淹《岳阳楼记》", "meaning": "***在天下人忧愁之前先忧愁，在天下人快乐之后才快乐。士人的担当，千古第一句。***", "category": "*二、情深缘浅"}, {"id": 304, "collection": "cy", "term": "冰壶秋月", "chars": 4, "pinyin": "", "source": "许有壬《水龙吟》", "meaning": "*冰做的壶，秋天的月亮。心地澄澈，光明磊落。*", "category": "*二、情深缘浅"}, {"id": 305, "collection": "cy", "term": "出淤泥而不染，濯清涟而不妖", "chars": 12, "pinyin": "", "source": "周敦颐《爱莲说》", "meaning": "*从淤泥里长出来却不沾染污秽，在清水里洗过却不妖媚。莲花，是中国人的君子。*", "category": "*二、情深缘浅"}, {"id": 306, "collection": "cy", "term": "男儿何不带吴钩，收取关山五十州", "chars": 14, "pinyin": "", "source": "李贺《南园》", "meaning": "**好男儿为什么不佩吴钩，去收复关山五十州？**", "category": "*一、光阴如流水"}, {"id": 307, "collection": "cy", "term": "刑天舞干戚，猛志固常在", "chars": 10, "pinyin": "", "source": "陶渊明《读山海经》", "meaning": "*刑天被砍了头，还用乳为目、脐为口，挥舞干戚。反抗的精神，不死。*", "category": "*二、情深缘浅"}, {"id": 308, "collection": "cy", "term": "出师未捷身先死，长使英雄泪满襟", "chars": 14, "pinyin": "", "source": "杜甫《蜀相》", "meaning": "***北伐尚未成功，诸葛亮先已病逝，让后世英雄泪湿衣襟。***", "category": "*二、情深缘浅"}, {"id": 309, "collection": "cy", "term": "位卑未敢忘忧国，事定犹须待阖棺", "chars": 14, "pinyin": "", "source": "陆游《病起书怀》", "meaning": "*身份再卑微，也不敢忘了忧国；是非功过，要等盖棺才能定论。*", "category": "*二、情深缘浅"}, {"id": 310, "collection": "cy", "term": "千淘万漉虽辛苦，吹尽狂沙始到金", "chars": 14, "pinyin": "", "source": "刘禹锡《浪淘沙》", "meaning": "*千遍淘洗虽然辛苦，吹尽狂沙才见真金。真金不怕火炼，好东西都经得起打磨。*", "category": "*二、情深缘浅"}, {"id": 311, "collection": "cy", "term": "鞠躬尽瘁，死而后已", "chars": 8, "pinyin": "", "source": "诸葛亮《后出师表》", "meaning": "***勤勤恳恳耗尽心力，到死才停。诸葛亮用一生践行了这八个字。***", "category": "*二、情深缘浅"}, {"id": 312, "collection": "cy", "term": "宁可枝头抱香死，何曾吹落北风中", "chars": 14, "pinyin": "", "source": "郑思肖《寒菊》", "meaning": "*宁愿在枝头抱香而死，也不肯被北风吹落。亡国诗人郑思肖的节气，硬到骨头里。*", "category": "*二、情深缘浅"}, {"id": 313, "collection": "cy", "term": "安能摧眉折腰事权贵，使我不得开心颜", "chars": 16, "pinyin": "", "source": "李白《梦游天姥吟留别》", "meaning": "***怎么能低头弯腰伺候权贵，让我不能开心？李白用一句诗，挺直了所有文人的脊梁。***", "category": "*二、情深缘浅"}, {"id": 314, "collection": "cy", "term": "岂不罹凝寒，松柏有本性", "chars": 10, "pinyin": "", "source": "刘桢《赠从弟》", "meaning": "**难道松柏不遭受严寒？只是它有耐寒的本性。刘桢写松，写的是自己的骨气。**", "category": "*一、光阴如流水"}, {"id": 315, "collection": "cy", "term": "岁寒，然后知松柏之后凋也", "chars": 11, "pinyin": "", "source": "《论语·子罕》", "meaning": "***天冷了，才知道松柏最后凋零。患难时，才见真正的品格。***", "category": "*二、情深缘浅"}, {"id": 316, "collection": "cy", "term": "我自横刀向天笑，去留肝胆两昆仑", "chars": 14, "pinyin": "", "source": "谭嗣同《狱中题壁》", "meaning": "*我横着刀向天大笑，留下和死去，都是肝胆昆仑。戊戌六君子，死得壮烈。*", "category": "*二、情深缘浅"}, {"id": 317, "collection": "cy", "term": "匈奴未灭，何以家为", "chars": 8, "pinyin": "", "source": "《史记·卫将军骠骑列传》", "meaning": "**匈奴还没消灭，要家做什么？霍去病拒受宅第，一语立起少年将军的丰碑。**", "category": "*一、光阴如流水"}, {"id": 318, "collection": "cy", "term": "黄沙百战穿金甲，不破楼兰终不还", "chars": 14, "pinyin": "", "source": "王昌龄《从军行》", "meaning": "*黄沙里身经百战，铁甲都磨穿了，不打败敌人绝不回还。*", "category": "*二、情深缘浅"}, {"id": 319, "collection": "cy", "term": "苔花如米小，也学牡丹开", "chars": 10, "pinyin": "", "source": "袁枚《苔》", "meaning": "*苔花小如米粒，也要像牡丹一样绽放。再平凡的生命，也值得盛放。*", "category": "*二、情深缘浅"}, {"id": 320, "collection": "cy", "term": "人生自古谁无死，留取丹心照汗青", "chars": 14, "pinyin": "", "source": "文天祥《过零丁洋》", "meaning": "*人固有一死，但要死得明明白白、堂堂正正。文天祥用一生践行了这两句。*", "category": "*二、情深缘浅"}, {"id": 321, "collection": "cy", "term": "青山遮不住，毕竟东流去", "chars": 10, "pinyin": "", "source": "辛弃疾《菩萨蛮》", "meaning": "*青山挡不住江水东流。大势所趋，谁也拦不住。*", "category": "*二、情深缘浅"}, {"id": 322, "collection": "cy", "term": "精卫衔微木，将以填沧海", "chars": 10, "pinyin": "", "source": "陶渊明《读山海经》", "meaning": "*精卫鸟衔着小树枝，立志填平大海。不自量力的背后，是不肯认输。*", "category": "*二、情深缘浅"}, {"id": 323, "collection": "cy", "term": "长风破浪会有时，直挂云帆济沧海", "chars": 14, "pinyin": "", "source": "李白《行路难》", "meaning": "*总有一天能乘风破浪，高挂云帆，横渡沧海。李白失意时，依然豪情万丈。*", "category": "*二、情深缘浅"}, {"id": 324, "collection": "cy", "term": "林下风致", "chars": 4, "pinyin": "", "source": "《世说新语·贤媛》", "meaning": "*谢道韫的气质，像竹林名士一样洒脱。形容女子风度，这是最高级别的夸奖。*", "category": "*二、情深缘浅"}, {"id": 325, "collection": "cy", "term": "千磨万击还坚劲，任尔东西南北风", "chars": 14, "pinyin": "", "source": "郑燮《竹石》", "meaning": "*千磨万击依然坚韧，任凭东西南北风。竹子如此，人也该如此。*", "category": "*二、情深缘浅"}, {"id": 326, "collection": "cy", "term": "天下兴亡，匹夫有责", "chars": 8, "pinyin": "", "source": "顾炎武《日知录》", "meaning": "***国家兴亡，每个人都有责任。***", "category": "*二、情深缘浅"}, {"id": 327, "collection": "cy", "term": "王师北定中原日，家祭无忘告乃翁", "chars": 14, "pinyin": "", "source": "陆游《示儿》", "meaning": "***朝廷大军收复中原那天，家祭时别忘了告诉父亲。陆游的遗言，是至死不渝的爱国。***", "category": "*二、情深缘浅"}, {"id": 328, "collection": "cy", "term": "壮心未与年俱老，死去犹能作鬼雄", "chars": 14, "pinyin": "", "source": "陆游《书愤》", "meaning": "**雄心壮志不随年老而衰，死后还能做鬼中英雄。**", "category": "*一、光阴如流水"}, {"id": 329, "collection": "cy", "term": "只解沙场为国死，何须马革裹尸还", "chars": 14, "pinyin": "", "source": "徐锡麟《出塞》", "meaning": "***只知道在沙场为国战死，何须用马皮裹尸还乡？***", "category": "*二、情深缘浅"}, {"id": 330, "collection": "cy", "term": "惶恐滩头说惶恐，零丁洋里叹零丁", "chars": 14, "pinyin": "", "source": "文天祥《过零丁洋》", "meaning": "*惶恐滩头说惶恐，零丁洋里叹零丁。地名与人名对仗，字字是血泪。*", "category": "*二、情深缘浅"}, {"id": 331, "collection": "cy", "term": "宁为玉碎，不为瓦全", "chars": 8, "pinyin": "", "source": "《北齐书·元景安传》", "meaning": "*宁可做玉被打碎，也不做瓦片保全自己。中国人讲气节，这四个字最硬。*", "category": "*二、情深缘浅"}, {"id": 332, "collection": "cy", "term": "生当作人杰，死亦为鬼雄", "chars": 10, "pinyin": "", "source": "李清照《夏日绝句》", "meaning": "*活着要做人中豪杰，死了也要做鬼中英雄。李清照一个女子，写出了最硬的骨气。*", "category": "*二、情深缘浅"}, {"id": 333, "collection": "cy", "term": "至今思项羽，不肯过江东", "chars": 10, "pinyin": "", "source": "李清照《夏日绝句》", "meaning": "*至今还思念项羽，宁死不肯过江东。李清照借项羽，讽刺南渡的朝廷。*", "category": "*二、情深缘浅"}, {"id": 334, "collection": "cy", "term": "但使龙城飞将在，不教胡马度阴山", "chars": 14, "pinyin": "", "source": "王昌龄《出塞》", "meaning": "***只要有李广那样的飞将军在，绝不让胡人骑兵越过阴山。***", "category": "*二、情深缘浅"}, {"id": 335, "collection": "cy", "term": "疾风知劲草，板荡识诚臣", "chars": 10, "pinyin": "", "source": "李世民《赐萧瑀》", "meaning": "*大风中才知草之坚韧，乱世中才识臣之忠诚。唐太宗写忠臣，写了八个字。*", "category": "*二、情深缘浅"}, {"id": 336, "collection": "cy", "term": "富贵不能淫，贫贱不能移，威武不能屈", "chars": 15, "pinyin": "", "source": "《孟子·滕文公下》", "meaning": "*富贵不能迷惑，贫贱不能动摇，威武不能屈服。孟子说的\"大丈夫\"，三句话立住了。*", "category": "*二、情深缘浅"}, {"id": 337, "collection": "cy", "term": "穷则独善其身，达则兼善天下", "chars": 12, "pinyin": "", "source": "《孟子·尽心上》", "meaning": "*不得志就修养自身，得志就造福天下。孟子的进退之道，是中国士人的理想。*", "category": "*二、情深缘浅"}, {"id": 338, "collection": "cy", "term": "三军可夺帅也，匹夫不可夺志也", "chars": 13, "pinyin": "", "source": "《论语·子罕》", "meaning": "*三军可以夺去主帅，一个普通人却不可夺去志向。孔子的这句话，给普通人撑腰。*", "category": "*二、情深缘浅"}, {"id": 339, "collection": "cy", "term": "士不可以不弘毅，任重而道远", "chars": 12, "pinyin": "", "source": "《论语·泰伯》", "meaning": "*读书人不能不刚强勇毅，因为责任重大、道路遥远。曾子的话，是士人的座右铭。*", "category": "*二、情深缘浅"}, {"id": 340, "collection": "cy", "term": "路漫漫其修远兮，吾将上下而求索", "chars": 14, "pinyin": "", "source": "屈原《离骚》", "meaning": "*道路漫长而遥远，我要上天入地去追寻。屈原求索，求索了一生。*", "category": "*二、情深缘浅"}, {"id": 341, "collection": "cy", "term": "万里赴戎机，关山度若飞", "chars": 10, "pinyin": "", "source": "《木兰诗》", "meaning": "**奔赴万里战场，飞越重重关山。木兰从军，从这句开始有了英姿。**", "category": "*一、光阴如流水"}, {"id": 342, "collection": "cy", "term": "一身转战三千里，一剑曾当百万师", "chars": 14, "pinyin": "", "source": "王维《老将行》", "meaning": "**一生转战三千里，一把剑曾挡百万大军。写老将的战功，气吞山河。**", "category": "*一、光阴如流水"}, {"id": 343, "collection": "cy", "term": "我醉欲眠卿且去，明朝有意抱琴来", "chars": 14, "pinyin": "", "source": "李白《山中与幽人对酌》", "meaning": "**我喝醉了要睡，你先走吧；明天若还有兴致，抱琴再来。李白的随意，随得有风度。**", "category": "*一、光阴如流水"}, {"id": 344, "collection": "cy", "term": "举世皆浊我独清，众人皆醉我独醒", "chars": 14, "pinyin": "", "source": "屈原《渔父》", "meaning": "*全世界都浑浊，只有我清白；众人都醉了，只有我清醒。屈原的孤独，清醒得刺眼。*", "category": "*二、情深缘浅"}, {"id": 345, "collection": "cy", "term": "壁立千仞，无欲则刚", "chars": 8, "pinyin": "", "source": "林则徐自勉联", "meaning": "**像峭壁矗立千仞，没有私欲，自然刚强。与“海纳百川，有容乃大”齐名。**", "category": "*一、光阴如流水"}, {"id": 346, "collection": "cy", "term": "君子坦荡荡，小人长戚戚", "chars": 10, "pinyin": "", "source": "《论语·述而》", "meaning": "***君子心胸开阔坦荡，小人常常忧愁局促。***", "category": "*二、情深缘浅"}, {"id": 347, "collection": "cy", "term": "君子和而不同，小人同而不和", "chars": 12, "pinyin": "", "source": "《论语·子路》", "meaning": "***君子和谐相处却各有主见，小人盲从附和却面和心不和。***", "category": "*二、情深缘浅"}, {"id": 348, "collection": "cy", "term": "见贤思齐焉，见不贤而内自省也", "chars": 13, "pinyin": "", "source": "《论语·里仁》", "meaning": "***见到贤人就想向他看齐，见到不贤的人就反省自己有没有同样的问题。***", "category": "*二、情深缘浅"}, {"id": 349, "collection": "cy", "term": "志士仁人，无求生以害仁，有杀身以成仁", "chars": 16, "pinyin": "", "source": "《论语·卫灵公》", "meaning": "***志士仁人，不因贪生而损害仁德，只会牺牲生命来成全仁德。***", "category": "*二、情深缘浅"}, {"id": 350, "collection": "cy", "term": "人固有一死，或重于泰山，或轻于鸿毛", "chars": 15, "pinyin": "", "source": "司马迁《报任安书》", "meaning": "***人总有一死，有的比泰山还重，有的比鸿毛还轻。***", "category": "*二、情深缘浅"}, {"id": 351, "collection": "cy", "term": "知其不可而为之", "chars": 7, "pinyin": "", "source": "《论语·宪问》", "meaning": "***明知做不到，却偏要去做。孔子的倔强，是明知徒劳仍不放弃。***", "category": "*二、情深缘浅"}, {"id": 352, "collection": "cy", "term": "吾日三省吾身", "chars": 6, "pinyin": "", "source": "《论语·学而》", "meaning": "**我每天多次反省自己：为人谋而不忠乎？与朋友交而不信乎？传不习乎？**", "category": "*一、光阴如流水"}, {"id": 353, "collection": "cy", "term": "君子求诸己，小人求诸人", "chars": 10, "pinyin": "", "source": "《论语·卫灵公》", "meaning": "***君子遇事靠自己，小人遇事怪别人。***", "category": "*二、情深缘浅"}, {"id": 354, "collection": "cy", "term": "高山仰止，景行行止", "chars": 8, "pinyin": "", "source": "《诗经·小雅·车舝》", "meaning": "*高山让人仰望，大道让人行走。后世用这两句，赞美品德高尚的人。*", "category": "*二、情深缘浅"}, {"id": 355, "collection": "cy", "term": "桃李不言，下自成蹊", "chars": 8, "pinyin": "", "source": "《史记·李将军列传》", "meaning": "*桃树李树不说话，树下却自然踩出小路。司马迁写李广：人好，自有人来。*", "category": "*二、情深缘浅"}, {"id": 356, "collection": "cy", "term": "天行健，君子以自强不息", "chars": 10, "pinyin": "", "source": "《周易·乾卦》", "meaning": "***天道运行刚健不息，君子也应奋发图强、永不停歇。***", "category": "*二、情深缘浅"}, {"id": 357, "collection": "cy", "term": "穷则变，变则通，通则久", "chars": 9, "pinyin": "", "source": "《周易·系辞下》", "meaning": "***穷困到极点就要变革，变革就能通达，通达就能长久。***", "category": "*二、情深缘浅"}, {"id": 358, "collection": "cy", "term": "君子喻于义，小人喻于利", "chars": 10, "pinyin": "", "source": "《论语·里仁》", "meaning": "**君子懂得的是道义，小人懂得的是利益。**", "category": "*一、光阴如流水"}, {"id": 359, "collection": "cy", "term": "知者不惑，仁者不忧，勇者不惧", "chars": 12, "pinyin": "", "source": "《论语·子罕》", "meaning": "*智者不迷惑，仁者不忧愁，勇者不恐惧。孔子说的三达德，是君子的标配。*", "category": "*二、情深缘浅"}, {"id": 360, "collection": "cy", "term": "岁寒三友", "chars": 4, "pinyin": "", "source": "明清以来常用", "meaning": "*松、竹、梅，寒冬不凋、不屈、不谢。中国人把坚贞，种在了三棵植物上。*", "category": "*二、情深缘浅"}, {"id": 361, "collection": "cy", "term": "中通外直，不蔓不枝", "chars": 8, "pinyin": "", "source": "周敦颐《爱莲说》", "meaning": "*莲茎中空外直，不生枝蔓，不长枝节。周敦颐写莲，写的是君子立身。*", "category": "*二、情深缘浅"}, {"id": 362, "collection": "cy", "term": "香远益清，亭亭净植", "chars": 8, "pinyin": "", "source": "周敦颐《爱莲说》", "meaning": "*香气越远越清，亭亭净立。周敦颐写莲，写出了君子的品格。*", "category": "*二、情深缘浅"}, {"id": 363, "collection": "cy", "term": "可远观而不可亵玩焉", "chars": 9, "pinyin": "", "source": "周敦颐《爱莲说》", "meaning": "*可以远远观赏，却不可轻慢把玩。周敦颐写莲，写出了君子的庄重。*", "category": "*二、情深缘浅"}, {"id": 364, "collection": "cy", "term": "斯是陋室，惟吾德馨", "chars": 8, "pinyin": "", "source": "刘禹锡《陋室铭》", "meaning": "*这是简陋的屋子，只因我的品德而芬芳。刘禹锡住陋室，住出了骄傲。*", "category": "*二、情深缘浅"}, {"id": 365, "collection": "cy", "term": "无丝竹之乱耳，无案牍之劳形", "chars": 12, "pinyin": "", "source": "刘禹锡《陋室铭》", "meaning": "*没有丝竹之声扰乱耳朵，没有官府文书劳累身体。刘禹锡的清净，清净得自得。*", "category": "*二、情深缘浅"}, {"id": 366, "collection": "cy", "term": "谈笑有鸿儒，往来无白丁", "chars": 10, "pinyin": "", "source": "刘禹锡《陋室铭》", "meaning": "*说笑的都是博学之人，来往的没有平民。刘禹锡写陋室，写的是朋友圈。*", "category": "*二、情深缘浅"}, {"id": 367, "collection": "cy", "term": "君子之交淡如水", "chars": 7, "pinyin": "", "source": "《庄子·山木》", "meaning": "*君子之间的交情，淡得像水一样。庄子的交友观，淡而长久。*", "category": "*二、情深缘浅"}, {"id": 368, "collection": "cy", "term": "兰生幽谷，不为无人而不芳", "chars": 11, "pinyin": "", "source": "《孔子家语·在厄》", "meaning": "**兰花长在幽谷，不因无人欣赏就不香。君子修身，不因无人知晓而懈怠。**", "category": "*一、光阴如流水"}, {"id": 369, "collection": "cy", "term": "青松在东园，众草没其姿", "chars": 10, "pinyin": "", "source": "陶渊明《饮酒》", "meaning": "***青松挺立东园，被杂草埋没身姿。陶渊明写松，写的是自己。***", "category": "*二、情深缘浅"}, {"id": 370, "collection": "cy", "term": "愚公移山", "chars": 4, "pinyin": "", "source": "《列子·汤问》", "meaning": "***愚公决心搬走门前两座大山，子子孙孙无穷尽。不怕山高，就怕不挖。***", "category": "*二、情深缘浅"}, {"id": 371, "collection": "cy", "term": "穷且益坚，不坠青云之志", "chars": 10, "pinyin": "", "source": "王勃《滕王阁序》", "meaning": "*处境穷困，意志却更坚定，不放弃高远的志向。王勃写逆境，写出了青云志。*", "category": "*二、情深缘浅"}, {"id": 372, "collection": "cy", "term": "老当益壮，宁移白首之心", "chars": 10, "pinyin": "", "source": "王勃《滕王阁序》", "meaning": "*年纪越大，志气越壮，岂能改变白头之心？王勃写老骥，写得比曹操还壮。*", "category": "*二、情深缘浅"}, {"id": 373, "collection": "cy", "term": "酌贪泉而觉爽，处涸辙以犹欢", "chars": 12, "pinyin": "", "source": "王勃《滕王阁序》", "meaning": "*喝了贪泉的水，心却更加清爽；处在干涸的车辙里，依然欢快。王勃写操守，写在绝境中。*", "category": "*二、情深缘浅"}, {"id": 374, "collection": "cy", "term": "此中有真意，欲辨已忘言", "chars": 10, "pinyin": "", "source": "陶渊明《饮酒》", "meaning": "*这里面有真正的意趣，想分辨却已忘了该怎么说。陶渊明的悟，悟到无话可说。*", "category": "*二、情深缘浅"}, {"id": 375, "collection": "cy", "term": "采菊东篱下，悠然见南山", "chars": 10, "pinyin": "", "source": "陶渊明《饮酒》", "meaning": "*在东篱下采菊，不经意间抬头，看见了南山。中国田园诗的最高境界，就这十个字。*", "category": "*二、情深缘浅"}, {"id": 376, "collection": "cy", "term": "书山有路勤为径，学海无涯苦作舟", "chars": 14, "pinyin": "", "source": "韩愈治学名联", "meaning": "***书山有路，勤奋是路；学海无涯，苦读作舟。***", "category": "*六、文墨风流"}, {"id": 377, "collection": "cy", "term": "腹有诗书气自华", "chars": 7, "pinyin": "", "source": "苏轼《和董传留别》", "meaning": "*肚子里装着诗书，气质自然光彩照人。读书，是最高级的\"整容\"。*", "category": "*六、文墨风流"}, {"id": 378, "collection": "cy", "term": "入木三分", "chars": 4, "pinyin": "", "source": "唐·张怀瓘《书断》", "meaning": "*王羲之写字的木板，墨迹透进木头三分。笔力之深，功夫之深。*", "category": "*六、文墨风流"}, {"id": 379, "collection": "cy", "term": "呕心沥血", "chars": 4, "pinyin": "", "source": "唐·李商隐《李贺小传》", "meaning": "*李贺出门骑驴，背锦囊，想到好句子就写下投进囊中，母亲心疼地说：\"这孩子要呕出心才肯罢休。*", "category": "*六、文墨风流"}, {"id": 380, "collection": "cy", "term": "十年寒窗无人问，一举成名天下知", "chars": 14, "pinyin": "", "source": "元·高明《琵琶记》", "meaning": "**十年苦读无人问津，一举成名天下皆知。**", "category": "*一、光阴如流水"}, {"id": 381, "collection": "cy", "term": "少年易老学难成，一寸光阴不可轻", "chars": 14, "pinyin": "", "source": "朱熹《偶成》", "meaning": "*少年容易老，学问难做成，一寸光阴都不该轻看。朱熹的劝学，字字如钟。*", "category": "*六、文墨风流"}, {"id": 382, "collection": "cy", "term": "纸上得来终觉浅，绝知此事要躬行", "chars": 14, "pinyin": "", "source": "陆游《冬夜读书示子聿》", "meaning": "*纸上得来的终究浅，真要弄明白，必须亲自去做。古人的\"知行合一\"。*", "category": "*六、文墨风流"}, {"id": 383, "collection": "cy", "term": "笔走龙蛇", "chars": 4, "pinyin": "", "source": "唐·李白《草书歌行》", "meaning": "*笔一挥，像龙蛇游走。夸书法，这四个字最痛快。*", "category": "*六、文墨风流"}, {"id": 384, "collection": "cy", "term": "熟读唐诗三百首，不会作诗也会吟", "chars": 14, "pinyin": "", "source": "孙洙《唐诗三百首序》", "meaning": "***读熟了三百首唐诗，不会写诗也会吟。多读，是写作最简单的门径。***", "category": "*六、文墨风流"}, {"id": 385, "collection": "cy", "term": "一字千金", "chars": 4, "pinyin": "", "source": "《史记·吕不韦列传》", "meaning": "*吕不韦编《吕氏春秋》，挂在咸阳城门上，谁能改一个字，赏千金。文人的底气，一字值千金。*", "category": "*六、文墨风流"}, {"id": 386, "collection": "cy", "term": "江郎才尽", "chars": 4, "pinyin": "", "source": "《南史·江淹传》", "meaning": "*江淹年轻时才华横溢，晚年梦中被还了笔，从此写不出好文章。才华会走，文思会尽，所以要珍惜。*", "category": "*六、文墨风流"}, {"id": 387, "collection": "cy", "term": "读书不觉已春深，一寸光阴一寸金", "chars": 14, "pinyin": "", "source": "王贞白《白鹿洞二首》", "meaning": "*读书读得忘了时间，一抬头，春天都深了。一寸光阴一寸金，古人早就懂。*", "category": "*六、文墨风流"}, {"id": 388, "collection": "cy", "term": "读书之乐乐何如，绿满窗前草不除", "chars": 14, "pinyin": "", "source": "翁森《四时读书乐》", "meaning": "**读书的乐趣怎么样？看窗前草长满，都不舍得除。**", "category": "*一、光阴如流水"}, {"id": 389, "collection": "cy", "term": "青春须早为，岂能长少年", "chars": 10, "pinyin": "", "source": "孟郊《劝学》", "meaning": "**青春要趁早努力，人哪能永远是少年？**", "category": "*一、光阴如流水"}, {"id": 390, "collection": "cy", "term": "不畏浮云遮望眼，自缘身在最高层", "chars": 14, "pinyin": "", "source": "王安石《登飞来峰》", "meaning": "*不怕浮云遮住眼睛，因为我站在最高处。格局打开，烦恼自然消散。*", "category": "*六、文墨风流"}, {"id": 391, "collection": "cy", "term": "旧书不厌百回读，熟读深思子自知", "chars": 14, "pinyin": "", "source": "苏轼《送安惇秀才失解西归》", "meaning": "***好书读一百遍也不厌，熟读深思，道理自然明白。***", "category": "*六、文墨风流"}, {"id": 392, "collection": "cy", "term": "敏捷诗千首，飘零酒一杯", "chars": 10, "pinyin": "", "source": "杜甫《不见》", "meaning": "**写诗敏捷，千首一挥而就；一生飘零，唯以酒相伴。杜甫悼李白，两句写尽平生。**", "category": "*一、光阴如流水"}, {"id": 393, "collection": "cy", "term": "新诗改罢自长吟", "chars": 7, "pinyin": "", "source": "杜甫《解闷》", "meaning": "**新诗改好，自己反复吟诵。杜甫写诗，认真到改完还要吟给自己听。**", "category": "*一、光阴如流水"}, {"id": 394, "collection": "cy", "term": "妙笔生花", "chars": 4, "pinyin": "", "source": "五代·王仁裕《开元天宝遗事》", "meaning": "*李白年少时梦见笔头上开出花来，从此文采飞扬。从此夸人写得好，就说\"妙笔生花\"。*", "category": "*六、文墨风流"}, {"id": 395, "collection": "cy", "term": "爱好由来落笔难，一诗千改始心安", "chars": 14, "pinyin": "", "source": "袁枚《遣兴》", "meaning": "**越爱写诗越觉落笔难，一首诗改上千遍才心安。**", "category": "*一、光阴如流水"}, {"id": 396, "collection": "cy", "term": "居高声自远，非是藉秋风", "chars": 10, "pinyin": "", "source": "虞世南《蝉》", "meaning": "*站得高，声音自然传得远，不是靠秋风帮忙。虞世南借蝉自喻：品行高，自然有声望。*", "category": "*六、文墨风流"}, {"id": 397, "collection": "cy", "term": "推敲", "chars": 2, "pinyin": "", "source": "宋·胡仔《苕溪渔隐丛话》引《刘公嘉话》", "meaning": "**贾岛琢磨“僧推月下门”还是“僧敲月下门”，撞了韩愈的车。从此“推敲”成了反复斟酌的代名词。**", "category": "*一、光阴如流水"}, {"id": 398, "collection": "cy", "term": "洛阳纸贵", "chars": 4, "pinyin": "", "source": "《晋书·左思传》", "meaning": "*左思写《三都赋》，全洛阳的人都抢着抄，纸价都涨了。什么叫爆款？这就是。*", "category": "*六、文墨风流"}, {"id": 399, "collection": "cy", "term": "才高八斗", "chars": 4, "pinyin": "", "source": "宋·无名氏《释常谈》", "meaning": "*谢灵运说：天下才共一石，曹子建独占八斗。从此\"才高八斗\"成了最高赞誉。*", "category": "*六、文墨风流"}, {"id": 400, "collection": "cy", "term": "十年磨一剑，霜刃未曾试", "chars": 10, "pinyin": "", "source": "贾岛《剑客》", "meaning": "***磨了十年的一把剑，寒光凛凛还未试锋。十年苦功，就等一朝出手。***", "category": "*六、文墨风流"}, {"id": 401, "collection": "cy", "term": "读书破万卷，下笔如有神", "chars": 10, "pinyin": "", "source": "杜甫《奉赠韦左丞丈二十二韵》", "meaning": "*读破万卷书，下笔就像有神助。杜甫用十个字，把读书与写作的关系写尽了。*", "category": "*六、文墨风流"}, {"id": 402, "collection": "cy", "term": "笔落惊风雨，诗成泣鬼神", "chars": 10, "pinyin": "", "source": "杜甫《寄李十二白二十韵》", "meaning": "*笔一落，风雨都惊；诗一成，鬼神都哭。杜甫夸李白，夸到了神鬼头上。*", "category": "*六、文墨风流"}, {"id": 403, "collection": "cy", "term": "文章者，经国之大业，不朽之盛事", "chars": 13, "pinyin": "", "source": "曹丕《典论·论文》", "meaning": "**文章是治理国家的大业，是永垂不朽的盛事。曹丕把文人地位提到了最高。**", "category": "*一、光阴如流水"}, {"id": 404, "collection": "cy", "term": "为人性僻耽佳句，语不惊人死不休", "chars": 14, "pinyin": "", "source": "杜甫《江上值水如海势聊短述》", "meaning": "*为人癖好琢磨佳句，语不惊人死都不罢休。杜甫的写作态度，就是跟自己较劲。*", "category": "*六、文墨风流"}, {"id": 405, "collection": "cy", "term": "笔底明珠无处卖，闲抛闲掷野藤中", "chars": 14, "pinyin": "", "source": "徐渭《题墨葡萄图》", "meaning": "**笔下画的葡萄像明珠，却无处可卖，只能闲抛在野藤之中。徐渭自喻怀才不遇。**", "category": "*一、光阴如流水"}, {"id": 406, "collection": "cy", "term": "文章本天成，妙手偶得之", "chars": 10, "pinyin": "", "source": "陆游《文章》", "meaning": "***好文章本是大自然的杰作，只是被妙手偶然得到。***", "category": "*六、文墨风流"}, {"id": 407, "collection": "cy", "term": "操千曲而后晓声，观千剑而后识器", "chars": 14, "pinyin": "", "source": "刘勰《文心雕龙·知音》", "meaning": "**弹过千支曲子才懂音乐，看过千把剑才识兵器。见多，才能识广。**", "category": "*一、光阴如流水"}, {"id": 408, "collection": "cy", "term": "书到用时方恨少，事非经过不知难", "chars": 14, "pinyin": "", "source": "《增广贤文》", "meaning": "***书到用时才恨读得少，事不经历不知有多难。***", "category": "*六、文墨风流"}, {"id": 409, "collection": "cy", "term": "庾信文章老更成，凌云健笔意纵横", "chars": 14, "pinyin": "", "source": "杜甫《戏为六绝句》", "meaning": "*庾信的文章越老越成熟，凌云健笔意气纵横。杜甫评庾信，评得精准。*", "category": "*六、文墨风流"}, {"id": 410, "collection": "cy", "term": "李杜文章在，光焰万丈长", "chars": 10, "pinyin": "", "source": "韩愈《调张籍》", "meaning": "*李白杜甫的文章还在，光芒万丈长存。韩愈一句，给李杜定了位。*", "category": "*六、文墨风流"}, {"id": 411, "collection": "cy", "term": "蚍蜉撼大树，可笑不自量", "chars": 10, "pinyin": "", "source": "韩愈《调张籍》", "meaning": "*蚂蚁想撼动大树，可笑不自量力。韩愈骂诋毁李杜的人，骂得痛快。*", "category": "*六、文墨风流"}, {"id": 412, "collection": "cy", "term": "业精于勤，荒于嬉；行成于思，毁于随", "chars": 14, "pinyin": "", "source": "韩愈《进学解》", "meaning": "*学业精于勤奋，荒废于嬉戏；德行成于思考，败坏于因循。韩愈的进学之道，句句是座右铭。*", "category": "*六、文墨风流"}, {"id": 413, "collection": "cy", "term": "我劝天公重抖擞，不拘一格降人才", "chars": 14, "pinyin": "", "source": "龚自珍《己亥杂诗》", "meaning": "***我劝老天重新振作，不拘一格降下人才。***", "category": "*六、文墨风流"}, {"id": 414, "collection": "cy", "term": "世事洞明皆学问，人情练达即文章", "chars": 14, "pinyin": "", "source": "《红楼梦》", "meaning": "***把世事看明白就是学问，把人情处理周到就是文章。***", "category": "*六、文墨风流"}, {"id": 415, "collection": "cy", "term": "文以载道", "chars": 4, "pinyin": "", "source": "周敦颐《通书》", "meaning": "***文章是用来承载道理的。文字的价值，在于它传递的思想。***", "category": "*六、文墨风流"}, {"id": 416, "collection": "cy", "term": "仰不愧于天，俯不怍于人", "chars": 10, "pinyin": "", "source": "《孟子·尽心上》", "meaning": "*抬头无愧于天，低头无愧于人。孟子的这句话，是君子的底线。*", "category": "*六、文墨风流"}, {"id": 417, "collection": "cy", "term": "学而不思则罔，思而不学则殆", "chars": 12, "pinyin": "", "source": "《论语·为政》", "meaning": "*只学不思就迷惘，只思不学就危险。孔子的学习方法论，至今管用。*", "category": "*六、文墨风流"}, {"id": 418, "collection": "cy", "term": "温故而知新，可以为师矣", "chars": 10, "pinyin": "", "source": "《论语·为政》", "meaning": "*温习旧知识能有新体会，就可以做老师了。孔子教人，温故而知新。*", "category": "*六、文墨风流"}, {"id": 419, "collection": "cy", "term": "敏而好学，不耻下问", "chars": 8, "pinyin": "", "source": "《论语·公冶长》", "meaning": "*聪敏好学，不以向地位低的人请教为耻。孔子说：学问，不分上下。*", "category": "*六、文墨风流"}, {"id": 420, "collection": "cy", "term": "学而时习之，不亦说乎", "chars": 9, "pinyin": "", "source": "《论语·学而》", "meaning": "*学了又按时温习，不也很愉快吗？《论语》第一句，是学习的快乐。*", "category": "*六、文墨风流"}, {"id": 421, "collection": "cy", "term": "三人行，必有我师焉", "chars": 8, "pinyin": "", "source": "《论语·述而》", "meaning": "*三个人同行，其中一定有可以做我老师的人。孔子的谦虚，谦虚得朴素。*", "category": "*六、文墨风流"}, {"id": 422, "collection": "cy", "term": "知之为知之，不知为不知，是知也", "chars": 13, "pinyin": "", "source": "《论语·为政》", "meaning": "*知道就是知道，不知道就是不知道，这才是真正的智慧。孔子教人诚实。*", "category": "*六、文墨风流"}, {"id": 423, "collection": "cy", "term": "工欲善其事，必先利其器", "chars": 10, "pinyin": "", "source": "《论语·卫灵公》", "meaning": "*工匠要做好活，先要磨好工具。孔子说：做事先备好家伙。*", "category": "*六、文墨风流"}, {"id": 424, "collection": "cy", "term": "满招损，谦受益", "chars": 6, "pinyin": "", "source": "《尚书·大禹谟》", "meaning": "*自满招来损害，谦虚获得益处。《尚书》里的六个字，够用一辈子。*", "category": "*六、文墨风流"}, {"id": 425, "collection": "cy", "term": "学而优则仕，仕而优则学", "chars": 10, "pinyin": "", "source": "《论语·子张》", "meaning": "***学问有余就去做官，做官有余就去学习。学与仕，互为补充。***", "category": "*六、文墨风流"}, {"id": 426, "collection": "cy", "term": "知不足者好学，耻下问者自满", "chars": 12, "pinyin": "", "source": "林逋《省心录》", "meaning": "**知道自己不足的人好学，耻于向人请教的人自满。**", "category": "*一、光阴如流水"}, {"id": 427, "collection": "cy", "term": "学而不厌，诲人不倦", "chars": 8, "pinyin": "", "source": "《论语·述而》", "meaning": "***学习不厌烦，教人不疲倦。孔子说自己最得意的，就是这两点。***", "category": "*六、文墨风流"}, {"id": 428, "collection": "cy", "term": "他山之石，可以攻玉", "chars": 8, "pinyin": "", "source": "《诗经·小雅·鹤鸣》", "meaning": "*别山的石头，可以用来打磨玉器。别人的经验，可以成就自己。*", "category": "*六、文墨风流"}, {"id": 429, "collection": "cy", "term": "只要功夫深，铁杵磨成针", "chars": 10, "pinyin": "", "source": "宋·祝穆《方舆胜览》", "meaning": "**相传李白见老妪磨铁杵，问之，答“欲作针”。功夫深了，铁杵也能成针。**", "category": "*一、光阴如流水"}, {"id": 430, "collection": "cy", "term": "学然后知不足，教然后知困", "chars": 11, "pinyin": "", "source": "《礼记·学记》", "meaning": "*学了才知道自己不足，教了才知道自己有困惑。《礼记》说：教与学，互相成就。*", "category": "*六、文墨风流"}, {"id": 431, "collection": "cy", "term": "教学相长", "chars": 4, "pinyin": "", "source": "《礼记·学记》", "meaning": "*教和学互相促进。四个字，道出了教育的本质。*", "category": "*六、文墨风流"}, {"id": 432, "collection": "cy", "term": "青出于蓝而胜于蓝", "chars": 8, "pinyin": "", "source": "《荀子·劝学》", "meaning": "*青色从蓼蓝中提取，却比蓼蓝更青。荀子说：学生可以超过老师。*", "category": "*六、文墨风流"}, {"id": 433, "collection": "cy", "term": "冰水为之而寒于水", "chars": 8, "pinyin": "", "source": "《荀子·劝学》", "meaning": "*冰由水结成，却比水更冷。与\"青出于蓝\"并列，荀子劝学，劝出了后浪。*", "category": "*六、文墨风流"}, {"id": 434, "collection": "cy", "term": "锲而不舍，金石可镂", "chars": 8, "pinyin": "", "source": "《荀子·劝学》", "meaning": "*坚持雕刻不放弃，金石也能雕穿。荀子的这句，是坚持的说明书。*", "category": "*六、文墨风流"}, {"id": 435, "collection": "cy", "term": "不积跬步，无以至千里", "chars": 9, "pinyin": "", "source": "《荀子·劝学》", "meaning": "*不积累一步半步，就到不了千里之外。荀子说：大事都是小事攒的。*", "category": "*六、文墨风流"}, {"id": 436, "collection": "cy", "term": "不积小流，无以成江海", "chars": 9, "pinyin": "", "source": "《荀子·劝学》", "meaning": "*不汇聚细流，就成不了江海。与\"跬步\"连用，荀子把积累写透了。*", "category": "*六、文墨风流"}, {"id": 437, "collection": "cy", "term": "韦编三绝", "chars": 4, "pinyin": "", "source": "《史记·孔子世家》", "meaning": "***孔子读《周易》，把编竹简的皮绳磨断三次。书读百遍，其义自见。***", "category": "*六、文墨风流"}, {"id": 438, "collection": "cy", "term": "玉不琢，不成器；人不学，不知道", "chars": 12, "pinyin": "", "source": "《礼记·学记》", "meaning": "*玉不雕琢不成器物，人不学习不懂道理。《三字经》引了这句，成了启蒙格言。*", "category": "*六、文墨风流"}, {"id": 439, "collection": "cy", "term": "知之者不如好之者，好之者不如乐之者", "chars": 16, "pinyin": "", "source": "《论语·雍也》", "meaning": "*懂得学问的人，不如喜爱它的人；喜爱它的人，不如以它为乐的人。孔子分了三层境界。*", "category": "*六、文墨风流"}, {"id": 440, "collection": "cy", "term": "吾生也有涯，而知也无涯", "chars": 10, "pinyin": "", "source": "《庄子·养生主》", "meaning": "*我的生命是有限的，而知识是无限的。庄子的话，既是叹息，也是激励。*", "category": "*六、文墨风流"}, {"id": 441, "collection": "cy", "term": "博学之，审问之，慎思之，明辨之，笃行之", "chars": 15, "pinyin": "", "source": "《礼记·中庸》", "meaning": "*广博地学习，审慎地询问，周密地思考，清楚地辨析，坚定地实行。《中庸》的治学五步。*", "category": "*六、文墨风流"}, {"id": 442, "collection": "cy", "term": "好读书，不求甚解；每有会意，便欣然忘食", "chars": 16, "pinyin": "", "source": "陶渊明《五柳先生传》", "meaning": "*喜欢读书，不苛求字字弄懂；每有心得，就高兴得忘了吃饭。陶渊明的读书法，读的是快乐。*", "category": "*六、文墨风流"}, {"id": 443, "collection": "cy", "term": "读万卷书，行万里路", "chars": 8, "pinyin": "", "source": "明·董其昌《画禅室随笔》", "meaning": "***读一万卷书，走一万里路。读书与行路结合，才有真见识。***", "category": "*六、文墨风流"}, {"id": 444, "collection": "cy", "term": "因材施教", "chars": 4, "pinyin": "", "source": "《论语·先进》", "meaning": "**根据各人的资质进行教育。孔子对子路、冉有问同一问题，答法不同。**", "category": "*一、光阴如流水"}, {"id": 445, "collection": "cy", "term": "不愤不启，不悱不发", "chars": 8, "pinyin": "", "source": "《论语·述而》", "meaning": "**不到他苦思不解时不启发，不到他想说说不清时不引导。孔子的启发式教学。**", "category": "*一、光阴如流水"}, {"id": 446, "collection": "cy", "term": "十年树木，百年树人", "chars": 8, "pinyin": "", "source": "《管子·权修》", "meaning": "***种一棵树要十年，培养一个人要百年。教育是天下最慢也最重的事。***", "category": "*六、文墨风流"}, {"id": 447, "collection": "cy", "term": "学如逆水行舟，不进则退", "chars": 10, "pinyin": "", "source": "《增广贤文》", "meaning": "***学习像逆水行船，不前进就后退。***", "category": "*六、文墨风流"}, {"id": 448, "collection": "cy", "term": "千里之行，始于足下", "chars": 8, "pinyin": "", "source": "《老子》", "meaning": "***走千里路，是从脚下第一步开始的。***", "category": "*六、文墨风流"}, {"id": 449, "collection": "cy", "term": "书读百遍，其义自见", "chars": 8, "pinyin": "", "source": "《三国志·魏书》注", "meaning": "***书读一百遍，意思自然显现。***", "category": "*六、文墨风流"}, {"id": 450, "collection": "cy", "term": "立身以立学为先，立学以读书为本", "chars": 14, "pinyin": "", "source": "欧阳修《欧阳文忠公文集》", "meaning": "**立身处世以学习为先，学习以读书为本。**", "category": "*一、光阴如流水"}, {"id": 451, "collection": "cy", "term": "对牛弹琴", "chars": 4, "pinyin": "", "source": "汉·牟融《理惑论》", "meaning": "*对着牛弹琴，牛低头吃草，无动于衷。跟不懂的人讲道理，是白费力气。*", "category": "*六、文墨风流"}, {"id": 452, "collection": "cy", "term": "朝三暮四", "chars": 4, "pinyin": "", "source": "《庄子·齐物论》", "meaning": "*养猴人说早上三个晚上四个，猴子们发怒；改成早上四个晚上三个，猴子们就高兴。换个说法，效果天差地别。*", "category": "*六、文墨风流"}, {"id": 453, "collection": "cy", "term": "三人成虎", "chars": 4, "pinyin": "", "source": "《战国策·魏策二》", "meaning": "***三个人谎报街上有虎，听的人就信了。谣言重复多了，就变成“真相”。***", "category": "*六、文墨风流"}, {"id": 454, "collection": "cy", "term": "空花阳焰", "chars": 4, "pinyin": "", "source": "佛教经典譬喻", "meaning": "*空中之花，日光下浮动的焰影。看得见，摸不着。佛家说：执着这些，是自寻烦恼。*", "category": "*六、文墨风流"}, {"id": 455, "collection": "cy", "term": "杞人忧天", "chars": 4, "pinyin": "", "source": "《列子·天瑞》", "meaning": "*杞国人担心天塌下来。想得太远，是种病；但换个角度看，也是种浪漫。*", "category": "*六、文墨风流"}, {"id": 456, "collection": "cy", "term": "南柯一梦", "chars": 4, "pinyin": "", "source": "唐·李公佐《南柯太守传》", "meaning": "*淳于棼醉后梦入槐安国，做驸马、当太守，醒来发现只是槐树下的蚂蚁窝。荣华富贵，不过南柯一梦。*", "category": "*六、文墨风流"}, {"id": 457, "collection": "cy", "term": "掩耳盗铃", "chars": 4, "pinyin": "", "source": "《吕氏春秋·自知》", "meaning": "*捂着耳朵偷铃铛，以为自己听不见，别人也听不见。自欺欺人，古已有之。*", "category": "*六、文墨风流"}, {"id": 458, "collection": "cy", "term": "稻花香里说丰年，听取蛙声一片", "chars": 13, "pinyin": "", "source": "辛弃疾《西江月·夜行黄沙道中》", "meaning": "*稻花香里聊着丰收，蛙声一片。田园的夏夜，是中国人共同的乡愁。*", "category": "*六、文墨风流"}, {"id": 459, "collection": "cy", "term": "杯弓蛇影", "chars": 4, "pinyin": "", "source": "《晋书·乐广传》", "meaning": "*酒杯里映着墙上的弓，以为是蛇，吓出病来。很多时候，吓倒我们的只是自己的想象。*", "category": "*六、文墨风流"}, {"id": 460, "collection": "cy", "term": "画龙点睛", "chars": 4, "pinyin": "", "source": "《历代名画记·张僧繇》", "meaning": "*张僧繇画龙不点睛，点了睛，龙就破壁飞去。最关键的一笔，叫点睛之笔。*", "category": "*六、文墨风流"}, {"id": 461, "collection": "cy", "term": "唇亡齿寒", "chars": 4, "pinyin": "", "source": "《左传·僖公五年》", "meaning": "***嘴唇没了，牙齿就受寒。邻近的伙伴遭殃，自己也难保。***", "category": "*六、文墨风流"}, {"id": 462, "collection": "cy", "term": "东施效颦", "chars": 4, "pinyin": "", "source": "《庄子·天运》", "meaning": "*西施皱眉很美，东施学她皱眉，把人吓跑。模仿而不自知，是最大的尴尬。*", "category": "*六、文墨风流"}, {"id": 463, "collection": "cy", "term": "邯郸学步", "chars": 4, "pinyin": "", "source": "《庄子·秋水》", "meaning": "*去邯郸学人家走路，没学会，反而忘了自己怎么走，爬着回去。做自己，比学别人重要。*", "category": "*六、文墨风流"}, {"id": 464, "collection": "cy", "term": "狐假虎威", "chars": 4, "pinyin": "", "source": "《战国策·楚策一》", "meaning": "*狐狸借老虎的威风吓跑百兽。依仗别人的权势，终究不是自己的本事。*", "category": "*六、文墨风流"}, {"id": 465, "collection": "cy", "term": "南辕北辙", "chars": 4, "pinyin": "", "source": "《战国策·魏策四》", "meaning": "***要到南方的楚国，车却往北赶。方向错了，越努力离目标越远。***", "category": "*六、文墨风流"}, {"id": 466, "collection": "cy", "term": "焚琴煮鹤", "chars": 4, "pinyin": "", "source": "宋·《西清诗话》引李商隐《杂纂》", "meaning": "*把琴烧了当柴，把鹤煮了吃。糟蹋美好的东西，古人早就骂过。*", "category": "*六、文墨风流"}, {"id": 467, "collection": "cy", "term": "叶公好龙", "chars": 4, "pinyin": "", "source": "汉·刘向《新序》", "meaning": "*叶公爱龙爱到墙上雕满龙，真龙来了，吓得魂飞魄散。嘴上说爱，心里其实怕。*", "category": "*六、文墨风流"}, {"id": 468, "collection": "cy", "term": "刻舟求剑", "chars": 4, "pinyin": "", "source": "《吕氏春秋·察今》", "meaning": "*船走了，剑沉了，在船帮上刻个记号去找。世界在变，只有他还停在原地。*", "category": "*六、文墨风流"}, {"id": 469, "collection": "cy", "term": "守株待兔", "chars": 4, "pinyin": "", "source": "《韩非子·五蠹》", "meaning": "*守着树桩等兔子撞上来。把偶然当必然，是最贵的懒惰。*", "category": "*六、文墨风流"}, {"id": 470, "collection": "cy", "term": "望梅止渴", "chars": 4, "pinyin": "", "source": "《世说新语·假谲》", "meaning": "*曹操说前面有梅林，士兵们口水直流，就不渴了。先稳住局面，再解决问题，这是将才。*", "category": "*六、文墨风流"}, {"id": 471, "collection": "cy", "term": "指鹿为马", "chars": 4, "pinyin": "", "source": "《史记·秦始皇本纪》", "meaning": "***赵高牵来一头鹿，硬说是马。混淆是非、颠倒黑白，从两千年前就开始了。***", "category": "*六、文墨风流"}, {"id": 472, "collection": "cy", "term": "黄粱一梦", "chars": 4, "pinyin": "", "source": "唐·沈既济《枕中记》", "meaning": "*卢生在邯郸旅店做了一场富贵梦，醒来，店里的黄粱米饭还没煮熟。人生如梦，梦如人生。*", "category": "*六、文墨风流"}, {"id": 473, "collection": "cy", "term": "得鱼忘筌", "chars": 4, "pinyin": "", "source": "《庄子·外物》", "meaning": "*捕到鱼，就忘了渔具。庄子说的是：工具是手段，悟道才是目的。后来也用来讽喻忘恩负义。*", "category": "*六、文墨风流"}, {"id": 474, "collection": "cy", "term": "画蛇添足", "chars": 4, "pinyin": "", "source": "《战国策·齐策二》", "meaning": "*蛇画完了，又给它添上脚。多此一举，反而坏事。两千年前的笑话，今天还在上演。*", "category": "*六、文墨风流"}, {"id": 475, "collection": "cy", "term": "负荆请罪", "chars": 4, "pinyin": "", "source": "《史记·廉颇蔺相如列传》", "meaning": "***廉颇背着荆条向蔺相如请罪。认错，是最高级的勇敢。***", "category": "*六、文墨风流"}, {"id": 476, "collection": "cy", "term": "塞翁失马，焉知非福", "chars": 8, "pinyin": "", "source": "《淮南子·人间训》", "meaning": "*边塞老人丢了马，谁知不是福气？福祸相倚，是中国人最古老的辩证法。*", "category": "*六、文墨风流"}, {"id": 477, "collection": "cy", "term": "亡羊补牢，未为迟也", "chars": 8, "pinyin": "", "source": "《战国策·楚策四》", "meaning": "*羊丢了再补羊圈，还不算晚。犯了错及时补救，就是聪明的开始。*", "category": "*六、文墨风流"}, {"id": 478, "collection": "cy", "term": "井底之蛙，不知大海", "chars": 8, "pinyin": "", "source": "《庄子·秋水》", "meaning": "*井底的青蛙，不知道大海有多大。庄子说：人的眼界，决定了人的世界。*", "category": "*六、文墨风流"}, {"id": 479, "collection": "cy", "term": "揠苗助长，苗则槁矣", "chars": 8, "pinyin": "", "source": "《孟子·公孙丑上》", "meaning": "*拔苗助长，苗反而枯死了。孟子说：违背规律，好心也办坏事。*", "category": "*六、文墨风流"}, {"id": 480, "collection": "cy", "term": "自相矛盾", "chars": 4, "pinyin": "", "source": "《韩非子·难一》", "meaning": "*卖盾说盾无坚不摧，卖矛说矛无坚不破。自己打自己的脸，古已有之。*", "category": "*六、文墨风流"}, {"id": 481, "collection": "cy", "term": "买椟还珠", "chars": 4, "pinyin": "", "source": "《韩非子·外储说左上》", "meaning": "*买了匣子，把珍珠还了。楚人卖珠，郑人买匣——取舍之间，见人见识。*", "category": "*六、文墨风流"}, {"id": 482, "collection": "cy", "term": "滥竽充数", "chars": 4, "pinyin": "", "source": "《韩非子·内储说上》", "meaning": "*不会吹竽的南郭先生，混在乐队里充数。混得了一时，混不了一世。*", "category": "*六、文墨风流"}, {"id": 483, "collection": "cy", "term": "毛遂自荐", "chars": 4, "pinyin": "", "source": "《史记·平原君列传》", "meaning": "***毛遂自己推荐自己去楚国搬救兵。有本事，就要敢于站出来。***", "category": "*六、文墨风流"}, {"id": 484, "collection": "cy", "term": "螳臂当车", "chars": 4, "pinyin": "", "source": "《庄子·人间世》", "meaning": "*螳螂举起臂膀，想挡住车轮。不自量力的背后，也有一种悲壮。*", "category": "*六、文墨风流"}, {"id": 485, "collection": "cy", "term": "螳螂捕蝉，黄雀在后", "chars": 8, "pinyin": "", "source": "汉·韩婴《韩诗外传》", "meaning": "*螳螂要捕蝉，却不知黄雀在它身后。只顾眼前利益的人，往往忘了身后的危险。*", "category": "*六、文墨风流"}, {"id": 486, "collection": "cy", "term": "鹬蚌相争，渔翁得利", "chars": 8, "pinyin": "", "source": "《战国策·燕策二》", "meaning": "*鹬和蚌互不相让，结果渔翁捡了便宜。两败俱伤，便宜了第三个人。*", "category": "*六、文墨风流"}, {"id": 487, "collection": "cy", "term": "狡兔三窟", "chars": 4, "pinyin": "", "source": "《战国策·齐策四》", "meaning": "*狡猾的兔子有三个洞。冯谖为孟尝君\"市义\"，留了三窟退路。*", "category": "*六、文墨风流"}, {"id": 488, "collection": "cy", "term": "望洋兴叹", "chars": 4, "pinyin": "", "source": "《庄子·秋水》", "meaning": "*河伯看到大海，才知道自己渺小，抬头叹息。见过世面，才懂谦卑。*", "category": "*六、文墨风流"}, {"id": 489, "collection": "cy", "term": "庖丁解牛，游刃有余", "chars": 8, "pinyin": "", "source": "《庄子·养生主》", "meaning": "*庖丁宰牛，刀在骨缝间游走，有余地得很。熟能生巧，巧到从容。*", "category": "*六、文墨风流"}, {"id": 490, "collection": "cy", "term": "呆若木鸡", "chars": 4, "pinyin": "", "source": "《庄子·达生》", "meaning": "*斗鸡被训练到像木头鸡一样，反而天下无敌。真正的强大，是静下来。*", "category": "*六、文墨风流"}, {"id": 491, "collection": "cy", "term": "鹏程万里", "chars": 4, "pinyin": "", "source": "《庄子·逍遥游》", "meaning": "*大鹏鸟一飞，就是万里。庄子的志向，大得没边。*", "category": "*六、文墨风流"}, {"id": 492, "collection": "cy", "term": "至人无己，神人无功，圣人无名", "chars": 12, "pinyin": "", "source": "《庄子·逍遥游》", "meaning": "*至人忘我，神人无功，圣人不求名。庄子说：最高境界，是放下自己。*", "category": "*六、文墨风流"}, {"id": 493, "collection": "cy", "term": "北冥有鱼，其名为鲲", "chars": 8, "pinyin": "", "source": "《庄子·逍遥游》", "meaning": "*北海有一条鱼，名字叫鲲。庄子的想象力，从一条鱼开始。*", "category": "*六、文墨风流"}, {"id": 494, "collection": "cy", "term": "燕雀安知鸿鹄之志哉", "chars": 9, "pinyin": "", "source": "《史记·陈涉世家》", "meaning": "*燕雀怎么知道鸿鹄的志向？陈胜年轻时一句问，问出了反秦的第一声。*", "category": "*六、文墨风流"}, {"id": 495, "collection": "cy", "term": "王侯将相宁有种乎", "chars": 8, "pinyin": "", "source": "《史记·陈涉世家》", "meaning": "*王侯将相，难道是天生的种吗？陈胜的这句话，震动了整个封建社会。*", "category": "*六、文墨风流"}, {"id": 496, "collection": "cy", "term": "项庄舞剑，意在沛公", "chars": 8, "pinyin": "", "source": "《史记·项羽本纪》", "meaning": "*项庄舞剑，剑尖始终对着沛公。鸿门宴上的刀光剑影，都在舞姿里。*", "category": "*六、文墨风流"}, {"id": 497, "collection": "cy", "term": "破釜沉舟", "chars": 4, "pinyin": "", "source": "《史记·项羽本纪》", "meaning": "*砸了锅，沉了船，只留一条生路。项羽的决绝，决绝到赢了巨鹿。*", "category": "*六、文墨风流"}, {"id": 498, "collection": "cy", "term": "四面楚歌", "chars": 4, "pinyin": "", "source": "《史记·项羽本纪》", "meaning": "*四面唱起楚歌，项羽以为楚地全被占了。绝境，从心理上先被击溃。*", "category": "*六、文墨风流"}, {"id": 499, "collection": "cy", "term": "霸王别姬", "chars": 4, "pinyin": "", "source": "《史记·项羽本纪》", "meaning": "*项羽被围垓下，与虞姬诀别。英雄末路，美人在怀，一曲唱尽。*", "category": "*六、文墨风流"}, {"id": 500, "collection": "cy", "term": "约法三章", "chars": 4, "pinyin": "", "source": "《史记·高祖本纪》", "meaning": "*刘邦入咸阳，与百姓约法三章：杀人者死，伤人及盗抵罪。天下人心，从此归汉。*", "category": "*六、文墨风流"}, {"id": 501, "collection": "cy", "term": "韩信点兵，多多益善", "chars": 8, "pinyin": "", "source": "《史记·淮阴侯列传》", "meaning": "*韩信点兵，越多越好。韩信说：刘邦带兵不过十万，我带兵是多多益善。*", "category": "*六、文墨风流"}, {"id": 502, "collection": "cy", "term": "背水一战", "chars": 4, "pinyin": "", "source": "《史记·淮阴侯列传》", "meaning": "*韩信背水布阵，绝地求生。兵法说置之死地而后生，韩信做到了。*", "category": "*六、文墨风流"}, {"id": 503, "collection": "cy", "term": "明修栈道，暗度陈仓", "chars": 8, "pinyin": "", "source": "《史记·高祖本纪》", "meaning": "*明着修栈道，暗里渡陈仓。韩信的声东击西，骗过了项羽。*", "category": "*六、文墨风流"}, {"id": 504, "collection": "cy", "term": "萧规曹随", "chars": 4, "pinyin": "", "source": "《史记·曹相国世家》", "meaning": "*萧何定规矩，曹参照着办。最好的管理，有时是延续。*", "category": "*六、文墨风流"}, {"id": 505, "collection": "cy", "term": "运筹帷幄，决胜千里", "chars": 8, "pinyin": "", "source": "《史记·高祖本纪》", "meaning": "*在帐幕中谋划，决胜于千里之外。刘邦说：张良就是这样的人。*", "category": "*六、文墨风流"}, {"id": 506, "collection": "cy", "term": "桃李满天下", "chars": 5, "pinyin": "", "source": "唐·白居易《奉和令公绿野堂种花》", "meaning": "*令公的桃李满天下，何用堂前更种花。老师的学生遍布四方，就是最大的成就。*", "category": "*六、文墨风流"}, {"id": 507, "collection": "cy", "term": "近朱者赤，近墨者黑", "chars": 8, "pinyin": "", "source": "晋·傅玄《太子少傅箴》", "meaning": "*靠近朱砂就变红，靠近墨就变黑。环境塑造人，古人早就懂。*", "category": "*六、文墨风流"}, {"id": 508, "collection": "cy", "term": "一叶知秋", "chars": 4, "pinyin": "", "source": "《淮南子·说山训》", "meaning": "*见一叶落，而知岁之将暮。看见一片叶子，就知道秋天来了。*", "category": "*六、文墨风流"}, {"id": 509, "collection": "cy", "term": "明察秋毫", "chars": 4, "pinyin": "", "source": "《孟子·梁惠王上》", "meaning": "*能看清秋天鸟兽的细毛。孟子说：看得清细小的，才是真明察。*", "category": "*六、文墨风流"}, {"id": 510, "collection": "cy", "term": "缘木求鱼", "chars": 4, "pinyin": "", "source": "《孟子·梁惠王上》", "meaning": "*爬到树上去找鱼。孟子说：方向错了，再努力也白费。*", "category": "*六、文墨风流"}, {"id": 511, "collection": "cy", "term": "五十步笑百步", "chars": 6, "pinyin": "", "source": "《孟子·梁惠王上》", "meaning": "*逃了五十步的笑话逃了一百步的。孟子说：程度不同，本质一样。*", "category": "*六、文墨风流"}, {"id": 512, "collection": "cy", "term": "临渊羡鱼，不如退而结网", "chars": 10, "pinyin": "", "source": "《汉书·董仲舒传》", "meaning": "*站在水边羡慕鱼，不如回去织网。空想不如实干。*", "category": "*六、文墨风流"}, {"id": 513, "collection": "cy", "term": "不鸣则已，一鸣惊人", "chars": 8, "pinyin": "", "source": "《史记·滑稽列传》", "meaning": "*不叫则已，一叫就惊人。楚庄王三年不理政，一出手就称霸。*", "category": "*六、文墨风流"}, {"id": 514, "collection": "cy", "term": "不飞则已，一飞冲天", "chars": 8, "pinyin": "", "source": "《史记·滑稽列传》", "meaning": "*不飞则已，一飞冲天。与\"一鸣惊人\"连用，是沉潜者的爆发。*", "category": "*六、文墨风流"}, {"id": 515, "collection": "cy", "term": "狡兔死，走狗烹；飞鸟尽，良弓藏", "chars": 12, "pinyin": "", "source": "《史记·淮阴侯列传》", "meaning": "*兔子死了，猎狗被煮；飞鸟没了，好弓被藏。韩信临死前的感叹，是功臣的宿命。*", "category": "*六、文墨风流"}, {"id": 516, "collection": "cy", "term": "破镜重圆", "chars": 4, "pinyin": "", "source": "唐·孟棨《本事诗》", "meaning": "***乐昌公主与徐德言各执半面铜镜，乱世离散后又合镜重逢。***", "category": "*六、文墨风流"}, {"id": 517, "collection": "cy", "term": "城门失火，殃及池鱼", "chars": 8, "pinyin": "", "source": "《太平广记》", "meaning": "*城门失火，池里的鱼跟着遭殃。连累无辜，古已有之。*", "category": "*六、文墨风流"}, {"id": 518, "collection": "cy", "term": "人为刀俎，我为鱼肉", "chars": 8, "pinyin": "", "source": "《史记·项羽本纪》", "meaning": "*别人是刀和砧板，我是鱼肉。任人宰割的处境，八个字写尽。*", "category": "*六、文墨风流"}, {"id": 519, "collection": "cy", "term": "秋后算账", "chars": 4, "pinyin": "", "source": "明清以来常用语", "meaning": "*秋收之后，一并算账。中国人把\"来日方长\"用在了账上。*", "category": "*六、文墨风流"}, {"id": 520, "collection": "cy", "term": "人怕出名猪怕壮", "chars": 7, "pinyin": "", "source": "民间俗语", "meaning": "*人怕出名，猪怕长壮。树大招风，中国人最懂收敛。*", "category": "*六、文墨风流"}, {"id": 521, "collection": "cy", "term": "满城风雨", "chars": 4, "pinyin": "", "source": "宋·潘大临诗残句", "meaning": "*满城风雨近重阳。诗人潘大临写了一句，被催租人打断，这一句却成了千古名句。*", "category": "*六、文墨风流"}, {"id": 522, "collection": "cy", "term": "骑虎难下", "chars": 4, "pinyin": "", "source": "《晋书·温峤传》", "meaning": "*骑在虎背上，下来不了。进退两难，古人也这么说。*", "category": "*六、文墨风流"}, {"id": 523, "collection": "cy", "term": "雪上加霜", "chars": 4, "pinyin": "", "source": "宋·释道原《景德传灯录》", "meaning": "*雪上又加霜。倒霉的时候，坏事总爱扎堆。*", "category": "*六、文墨风流"}, {"id": 524, "collection": "cy", "term": "锦上添花", "chars": 4, "pinyin": "", "source": "宋·黄庭坚《了了庵颂》", "meaning": "*锦上再添花。好事的时候，好事也爱扎堆。*", "category": "*六、文墨风流"}, {"id": 525, "collection": "cy", "term": "一叶障目，不见泰山", "chars": 8, "pinyin": "", "source": "《鹖冠子·天则》", "meaning": "*一片叶子挡住眼睛，就看不见泰山。被小事蒙蔽，就看不到大局。*", "category": "*六、文墨风流"}, {"id": 526, "collection": "cy", "term": "人生如逆旅，我亦是行人", "chars": 10, "pinyin": "", "source": "苏轼《临江仙·送钱穆父》", "meaning": "*人生就像住旅店，我也是匆匆过客。看淡了聚散，也就看淡了悲欢。*", "category": "*八、千古一叹"}, {"id": 527, "collection": "cy", "term": "三十功名尘与土，八千里路云和月", "chars": 14, "pinyin": "", "source": "岳飞《满江红》", "meaning": "*三十年的功名如尘土，八千里的征途伴着云和月。岳飞把一生，都交给了国。*", "category": "*八、千古一叹"}, {"id": 528, "collection": "cy", "term": "昨夜西风凋碧树，独上高楼，望尽天涯路", "chars": 16, "pinyin": "", "source": "晏殊《蝶恋花》", "meaning": "*昨夜西风吹落了绿叶，一个人登上高楼，望断天涯路。治学的第一重境界：孤独地求索。*", "category": "*八、千古一叹"}, {"id": 529, "collection": "cy", "term": "赌书消得泼茶香，当时只道是寻常", "chars": 14, "pinyin": "", "source": "纳兰性德《浣溪沙》", "meaning": "**夫妻赌书泼茶的欢乐时光，当时只当是平常。失去后才懂，那些寻常最珍贵。**", "category": "*一、光阴如流水"}, {"id": 530, "collection": "cy", "term": "大江东去，浪淘尽，千古风流人物", "chars": 13, "pinyin": "", "source": "苏轼《念奴娇·赤壁怀古》", "meaning": "*大江东去，浪花淘尽多少英雄。苏轼站在赤壁，一眼望穿千年。*", "category": "*八、千古一叹"}, {"id": 531, "collection": "cy", "term": "欲穷千里目，更上一层楼", "chars": 10, "pinyin": "", "source": "王之涣《登鹳雀楼》", "meaning": "*想看更远，就再上一层楼。最简单的二十个字，藏着最朴素的人生哲学。*", "category": "*八、千古一叹"}, {"id": 532, "collection": "cy", "term": "回首向来萧瑟处，归去，也无风雨也无晴", "chars": 16, "pinyin": "", "source": "苏轼《定风波》", "meaning": "*回头看走过的风雨路，风也停了，雨也停了，无所谓阴晴。心境到了，风雨晴天都一样。*", "category": "*八、千古一叹"}, {"id": 533, "collection": "cy", "term": "会当凌绝顶，一览众山小", "chars": 10, "pinyin": "", "source": "杜甫《望岳》", "meaning": "*总有一天要登上泰山之顶，俯瞰群山都变小。青年杜甫的眼里，全是光。*", "category": "*八、千古一叹"}, {"id": 534, "collection": "cy", "term": "天生我材必有用，千金散尽还复来", "chars": 14, "pinyin": "", "source": "李白《将进酒》", "meaning": "*天生我才，必有用处；千金散尽，还能再来。这是中国人刻在骨子里的自信。*", "category": "*八、千古一叹"}, {"id": 535, "collection": "cy", "term": "衣带渐宽终不悔，为伊消得人憔悴", "chars": 14, "pinyin": "", "source": "柳永《蝶恋花》", "meaning": "*人瘦了，衣带松了，也不后悔。治学的第二重境界：执着的坚守。*", "category": "*八、千古一叹"}, {"id": 536, "collection": "cy", "term": "人有悲欢离合，月有阴晴圆缺，此事古难全", "chars": 17, "pinyin": "", "source": "苏轼《水调歌头》", "meaning": "*人间的悲欢，月亮的圆缺，自古以来就难两全。所以苏轼选择：但愿人长久，千里共婵娟。*", "category": "*八、千古一叹"}, {"id": 537, "collection": "cy", "term": "莫道桑榆晚，为霞尚满天", "chars": 10, "pinyin": "", "source": "刘禹锡《酬乐天咏老见示》", "meaning": "*别说太阳落山了，晚霞还能照亮满天。老了，也还有老年的灿烂。*", "category": "*八、千古一叹"}, {"id": 538, "collection": "cy", "term": "别人笑我太疯癫，我笑他人看不穿", "chars": 14, "pinyin": "", "source": "唐寅《桃花庵歌》", "meaning": "*别人笑我疯疯癫癫，我笑他们看不透。唐寅的狂，是看穿世事的清醒。*", "category": "*八、千古一叹"}, {"id": 539, "collection": "cy", "term": "此心安处是吾乡", "chars": 7, "pinyin": "", "source": "苏轼《定风波》", "meaning": "*试问岭南应不好，却道：此心安处是吾乡。心安定下来的地方，就是故乡。*", "category": "*八、千古一叹"}, {"id": 540, "collection": "cy", "term": "人生得意须尽欢，莫使金樽空对月", "chars": 14, "pinyin": "", "source": "李白《将进酒》", "meaning": "*人生得意的时候就该尽情欢乐，别让金杯空着对月。李白的豪情，就是活得痛快。*", "category": "*八、千古一叹"}, {"id": 541, "collection": "cy", "term": "蓦然回首，那人却在，灯火阑珊处", "chars": 13, "pinyin": "", "source": "辛弃疾《青玉案·元夕》", "meaning": "*回头一看，要找的人就在灯火稀疏的地方。治学的第三重境界：豁然开朗。*", "category": "*八、千古一叹"}, {"id": 542, "collection": "cy", "term": "不如意事常八九，可与人言无二三", "chars": 14, "pinyin": "", "source": "方岳《别子才司令》", "meaning": "*人生不如意的事十有八九，能说出口的却没有两三件。成年人的沉默，都在这句里。*", "category": "*八、千古一叹"}, {"id": 543, "collection": "cy", "term": "世事一场大梦，人生几度秋凉", "chars": 12, "pinyin": "", "source": "苏轼《西江月》", "meaning": "*世事像一场大梦，人生能经历几个秋天？苏轼被贬黄州，把沧桑看成了月凉如水。*", "category": "*八、千古一叹"}, {"id": 544, "collection": "cy", "term": "小舟从此逝，江海寄余生", "chars": 10, "pinyin": "", "source": "苏轼《临江仙·夜归临皋》", "meaning": "**驾一叶小舟从此远去，把余生寄托在江海。苏轼在黄州的深夜，想通了一切。**", "category": "*一、光阴如流水"}, {"id": 545, "collection": "cy", "term": "沉舟侧畔千帆过，病树前头万木春", "chars": 14, "pinyin": "", "source": "刘禹锡《酬乐天扬州初逢席上见赠》", "meaning": "*沉船旁边千帆竞过，病树前头万木逢春。旧事物消亡，新事物生长，这是自然的规律，也是人生的希望。*", "category": "*八、千古一叹"}, {"id": 546, "collection": "cy", "term": "前不见古人，后不见来者", "chars": 10, "pinyin": "", "source": "陈子昂《登幽州台歌》", "meaning": "*念天地之悠悠，独怆然而涕下。一个人站在时间的荒野上，孤独得惊天动地。*", "category": "*八、千古一叹"}, {"id": 547, "collection": "cy", "term": "宠辱不惊，看庭前花开花落；去留无意，望天上云卷云舒", "chars": 22, "pinyin": "", "source": "明·陈继儒《小窗幽记》", "meaning": "*受宠受辱都不惊，看庭前花开花落；去留都不在意，望天上云卷云舒。二十二字，一生的修为。*", "category": "*八、千古一叹"}, {"id": 548, "collection": "cy", "term": "古今多少事，都付笑谈中", "chars": 10, "pinyin": "", "source": "杨慎《临江仙》", "meaning": "*古今多少兴亡事，都成了喝茶时的笑谈。看透之后，云淡风轻。*", "category": "*八、千古一叹"}, {"id": 549, "collection": "cy", "term": "得之坦然，失之淡然，争其必然，顺其自然", "chars": 16, "pinyin": "", "source": "现代处世箴言", "meaning": "*得到时不狂喜，失去时不纠结，该争的尽力争，剩下的交给天意。这是中国人最高级的活法。*", "category": "*八、千古一叹"}, {"id": 550, "collection": "cy", "term": "行到水穷处，坐看云起时", "chars": 10, "pinyin": "", "source": "王维《终南别业》", "meaning": "*走到水流的尽头，就坐下来看云卷云起。王维的从容，是把绝路走成了风景。*", "category": "*八、千古一叹"}, {"id": 551, "collection": "cy", "term": "人生如梦，一尊还酹江月", "chars": 10, "pinyin": "", "source": "苏轼《念奴娇·赤壁怀古》", "meaning": "*人间如梦，洒一杯酒祭奠江月。苏轼凭吊赤壁，凭吊出了通透。*", "category": "*八、千古一叹"}, {"id": 552, "collection": "cy", "term": "清风徐来，水波不兴", "chars": 8, "pinyin": "", "source": "苏轼《前赤壁赋》", "meaning": "*清风慢慢吹来，水面波平浪静。苏轼泛舟的夜晚，平静得可以入梦。*", "category": "*八、千古一叹"}, {"id": 553, "collection": "cy", "term": "白露横江，水光接天", "chars": 8, "pinyin": "", "source": "苏轼《前赤壁赋》", "meaning": "*白露横亘江面，水光连接天际。苏轼写江景，写出了仙气。*", "category": "*八、千古一叹"}, {"id": 554, "collection": "cy", "term": "纵一苇之所如，凌万顷之茫然", "chars": 12, "pinyin": "", "source": "苏轼《前赤壁赋》", "meaning": "*任凭小船飘去，越过万顷的茫茫江水。苏轼泛舟，泛出了自由。*", "category": "*八、千古一叹"}, {"id": 555, "collection": "cy", "term": "羁鸟恋旧林，池鱼思故渊", "chars": 10, "pinyin": "", "source": "陶渊明《归园田居》", "meaning": "***笼中鸟想念旧日的树林，池中鱼思念原来的深潭。***", "category": "*八、千古一叹"}, {"id": 556, "collection": "cy", "term": "飘飘乎如遗世独立，羽化而登仙", "chars": 13, "pinyin": "", "source": "苏轼《前赤壁赋》", "meaning": "*飘飘然像脱离尘世，羽化成仙。苏轼的赤壁之夜，成了一夜神仙。*", "category": "*八、千古一叹"}, {"id": 557, "collection": "cy", "term": "我本楚狂人，凤歌笑孔丘", "chars": 10, "pinyin": "", "source": "李白《庐山谣寄卢侍御虚舟》", "meaning": "***我本是楚国的狂人，唱着凤歌嘲笑孔丘。李白的狂，狂得有出处。***", "category": "*八、千古一叹"}, {"id": 558, "collection": "cy", "term": "黄金白璧买歌笑，一醉累月轻王侯", "chars": 14, "pinyin": "", "source": "李白《忆旧游寄谯郡元参军》", "meaning": "**用黄金白璧买欢笑，一醉数月，把王侯都看轻。李白的狂放，到此极致。**", "category": "*一、光阴如流水"}, {"id": 559, "collection": "cy", "term": "人生七十古来稀", "chars": 7, "pinyin": "", "source": "杜甫《曲江二首》", "meaning": "***人活到七十岁，自古以来就稀少。杜甫感叹人生苦短。***", "category": "*八、千古一叹"}, {"id": 560, "collection": "cy", "term": "哀吾生之须臾，羡长江之无穷", "chars": 12, "pinyin": "", "source": "苏轼《前赤壁赋》", "meaning": "*哀叹人生短暂，羡慕长江无穷无尽。苏轼泛舟赤壁，写出了渺小与永恒。*", "category": "*八、千古一叹"}, {"id": 561, "collection": "cy", "term": "寄蜉蝣于天地，渺沧海之一粟", "chars": 12, "pinyin": "", "source": "苏轼《前赤壁赋》", "meaning": "*像蜉蝣寄生于天地，像沧海中的一粒粟。苏轼的宇宙观，让人渺小又释然。*", "category": "*八、千古一叹"}, {"id": 562, "collection": "cy", "term": "安得广厦千万间，大庇天下寒士俱欢颜", "chars": 16, "pinyin": "", "source": "杜甫《茅屋为秋风所破歌》", "meaning": "***怎么才能得到千万间大屋，让天下穷苦人都笑逐颜开？***", "category": "*八、千古一叹"}, {"id": 563, "collection": "cy", "term": "取之不尽，用之不竭", "chars": 8, "pinyin": "", "source": "苏轼《前赤壁赋》", "meaning": "*取它没有人禁止，用它用不完。苏轼写清风明月，写成了无尽的宝藏。*", "category": "*八、千古一叹"}, {"id": 564, "collection": "cy", "term": "日啖荔枝三百颗，不辞长作岭南人", "chars": 14, "pinyin": "", "source": "苏轼《惠州一绝》", "meaning": "***每天吃三百颗荔枝，甘愿永远做岭南人。苏轼被贬岭南，苦中作乐到极致。***", "category": "*八、千古一叹"}, {"id": 565, "collection": "cy", "term": "淮水东边旧时月，夜深还过女墙来", "chars": 14, "pinyin": "", "source": "刘禹锡《石头城》", "meaning": "**淮水东边的旧时明月，夜深了还照过城墙来。月还是旧月，城已非旧城。**", "category": "*一、光阴如流水"}, {"id": 566, "collection": "cy", "term": "梨花院落溶溶月，柳絮池塘淡淡风", "chars": 14, "pinyin": "", "source": "晏殊《寓意》", "meaning": "**梨花院落里月色溶溶，柳絮池塘边微风淡淡。写春夜的温柔，此句第一。**", "category": "*一、光阴如流水"}, {"id": 567, "collection": "cy", "term": "一点浩然气，千里快哉风", "chars": 10, "pinyin": "", "source": "苏轼《水调歌头·黄州快哉亭赠张偓佺》", "meaning": "***胸中一点浩然正气，便得千里快意长风。***", "category": "*八、千古一叹"}, {"id": 568, "collection": "cy", "term": "山高月小，水落石出", "chars": 8, "pinyin": "", "source": "苏轼《后赤壁赋》", "meaning": "*山高了月亮显小，水落了石头露出。苏轼写冬夜赤壁，写出了清冷的美。*", "category": "*八、千古一叹"}, {"id": 569, "collection": "cy", "term": "江流有声，断岸千尺", "chars": 8, "pinyin": "", "source": "苏轼《后赤壁赋》", "meaning": "*江流有声，陡峭的崖岸有千尺高。苏轼夜游，游出了险峻。*", "category": "*八、千古一叹"}, {"id": 570, "collection": "cy", "term": "霜露既降，木叶尽脱", "chars": 8, "pinyin": "", "source": "苏轼《后赤壁赋》", "meaning": "*霜露已降，树叶都落光了。苏轼写深秋，写出了萧瑟。*", "category": "*八、千古一叹"}, {"id": 571, "collection": "cy", "term": "人影在地，仰见明月", "chars": 8, "pinyin": "", "source": "苏轼《后赤壁赋》", "meaning": "*人影落在地上，抬头看见明月。苏轼夜行的孤独，孤独得干净。*", "category": "*八、千古一叹"}, {"id": 572, "collection": "cy", "term": "露重飞难进，风多响易沉", "chars": 10, "pinyin": "", "source": "骆宾王《在狱咏蝉》", "meaning": "**露水太重，蝉飞不动；风声太大，蝉鸣被淹没。骆宾王借蝉自况，怀才不遇。**", "category": "*一、光阴如流水"}, {"id": 573, "collection": "cy", "term": "九死南荒吾不恨，兹游奇绝冠平生", "chars": 14, "pinyin": "", "source": "苏轼《六月二十日夜渡海》", "meaning": "**贬到南方九死一生我也不恨，这一路的奇绝，是我平生之最。**", "category": "*一、光阴如流水"}, {"id": 574, "collection": "cy", "term": "大梦谁先觉，平生我自知", "chars": 10, "pinyin": "", "source": "罗贯中《三国演义》", "meaning": "*大梦谁先醒？平生只有我自己知道。诸葛亮出山前的这句诗，是醒着的梦。*", "category": "*八、千古一叹"}, {"id": 575, "collection": "cy", "term": "是非成败转头空。青山依旧在，几度夕阳红", "chars": 17, "pinyin": "", "source": "杨慎《临江仙》", "meaning": "*是非成败，一转头就空了；青山还在，夕阳红了几度。杨慎写历史，写成了空。*", "category": "*八、千古一叹"}, {"id": 576, "collection": "cy", "term": "白发渔樵江渚上，惯看秋月春风", "chars": 13, "pinyin": "", "source": "杨慎《临江仙》", "meaning": "*白发渔翁樵夫在江边，看惯了秋月春风。杨慎说：历史的尽头，是平常人。*", "category": "*八、千古一叹"}, {"id": 577, "collection": "cy", "term": "一壶浊酒喜相逢", "chars": 7, "pinyin": "", "source": "杨慎《临江仙》", "meaning": "*一壶浊酒，相逢就高兴。杨慎写人间，写出了淡泊的欢喜。*", "category": "*八、千古一叹"}, {"id": 578, "collection": "cy", "term": "今宵剩把银釭照，犹恐相逢是梦中", "chars": 14, "pinyin": "", "source": "晏几道《鹧鸪天》", "meaning": "**今夜把银灯照了又照，还怕这场相逢是在梦中。久别重逢的狂喜，写得极真。**", "category": "*一、光阴如流水"}, {"id": 579, "collection": "cy", "term": "周公恐惧流言日，王莽谦恭未篡时", "chars": 14, "pinyin": "", "source": "白居易《放言》", "meaning": "*周公被流言所困时，王莽谦恭还没篡位。白居易说：人心，要放到时间里去检验。*", "category": "*八、千古一叹"}, {"id": 580, "collection": "cy", "term": "落红不是无情物，化作春泥更护花", "chars": 14, "pinyin": "", "source": "龚自珍《己亥杂诗》", "meaning": "**落花不是无情之物，化作春泥，仍呵护着新花。**", "category": "*一、光阴如流水"}, {"id": 581, "collection": "cy", "term": "天行有常，不为尧存，不为桀亡", "chars": 12, "pinyin": "", "source": "《荀子·天论》", "meaning": "*大自然的运行有规律，不为尧而存在，不为桀而消亡。荀子说：天道无情，人间自强。*", "category": "*八、千古一叹"}, {"id": 582, "collection": "cy", "term": "制天命而用之", "chars": 6, "pinyin": "", "source": "《荀子·天论》", "meaning": "*掌握自然规律，利用它为人服务。荀子不信命，信人。*", "category": "*八、千古一叹"}, {"id": 583, "collection": "cy", "term": "国家不幸诗家幸，赋到沧桑句便工", "chars": 14, "pinyin": "", "source": "赵翼《题元遗山集》", "meaning": "**国家不幸，却是诗人的幸事；写到沧桑变迁，诗句才格外动人。**", "category": "*一、光阴如流水"}, {"id": 584, "collection": "cy", "term": "山不厌高，海不厌深。周公吐哺，天下归心", "chars": 16, "pinyin": "", "source": "曹操《短歌行》", "meaning": "*山不嫌高，海不嫌深；周公吐哺待贤，天下人心归附。曹操求贤，求到了天下。*", "category": "*八、千古一叹"}, {"id": 585, "collection": "cy", "term": "对酒当歌，人生几何？譬如朝露，去日苦多", "chars": 16, "pinyin": "", "source": "曹操《短歌行》", "meaning": "*对着酒应当高歌，人生能有多久？像早晨的露水，逝去的日子太多。曹操的慷慨，从感叹开始。*", "category": "*八、千古一叹"}, {"id": 586, "collection": "cy", "term": "月明星稀，乌鹊南飞。绕树三匝，何枝可依", "chars": 16, "pinyin": "", "source": "曹操《短歌行》", "meaning": "*月明星稀，乌鹊南飞；绕树飞了三圈，哪枝可以依靠？曹操写人才彷徨，写出了招揽之意。*", "category": "*八、千古一叹"}, {"id": 587, "collection": "cy", "term": "东临碣石，以观沧海", "chars": 8, "pinyin": "", "source": "曹操《观沧海》", "meaning": "*向东登上碣石山，来看沧海。曹操观海，观出了帝王气象。* *******", "category": "*八、千古一叹"}, {"id": 588, "collection": "cy", "term": "鸿雁在云鱼在水，惆怅此情难寄", "chars": 13, "pinyin": "", "source": "晏殊《清平乐》", "meaning": "**鸿雁在天上，鱼在水里，这份惆怅的心情却难以寄出。**", "category": "*一、光阴如流水"}, {"id": 589, "collection": "cy", "term": "晓来雨过，一池萍碎", "chars": 8, "pinyin": "", "source": "苏轼《水龙吟·次韵章质夫杨花词》", "meaning": "**清晨雨过，一池浮萍碎散。写杨花，也写飘零的人生。**", "category": "*一、光阴如流水"}, {"id": 590, "collection": "cy", "term": "日月之行，若出其中；星汉灿烂，若出其里", "chars": 16, "pinyin": "", "source": "曹操《观沧海》", "meaning": "*日月运行，好像从海中升起；星河灿烂，好像从海中涌出。曹操写海，写出了吞吐宇宙的气魄。* *******", "category": "*八、千古一叹"}, {"id": 591, "collection": "cy", "term": "便作春江都是泪，流不尽，许多愁", "chars": 13, "pinyin": "", "source": "秦观《江城子》", "meaning": "**就算整条春江都是泪水，也流不尽这许多愁。**", "category": "*一、光阴如流水"}, {"id": 592, "collection": "cy", "term": "举头望明月，低头思故乡", "chars": 10, "pinyin": "", "source": "李白《静夜思》", "meaning": "***抬起头看见明月，低下头想起故乡。二十个字，把乡愁说尽。***", "category": "*八、千古一叹"}, {"id": 593, "collection": "cy", "term": "天涯何处无芳草", "chars": 7, "pinyin": "", "source": "苏轼《蝶恋花·春景》", "meaning": "***天涯到处都有芳草。春色无边，不必为一枝凋谢悲伤。***", "category": "*八、千古一叹"}, {"id": 594, "collection": "cy", "term": "时人不识凌云木，直待凌云始道高", "chars": 14, "pinyin": "", "source": "杜荀鹤《小松》", "meaning": "*时人不识这棵凌云之木，等它高耸入云才说好。杜荀鹤写小松，写出了怀才不遇。*", "category": "*八、千古一叹"}, {"id": 595, "collection": "cy", "term": "不经一番寒彻骨，怎得梅花扑鼻香", "chars": 14, "pinyin": "", "source": "黄蘖禅师《上堂开示颂》", "meaning": "*不经过一番彻骨的寒冷，怎能得到梅花的扑鼻香？禅师的偈语，成了励志名言。*", "category": "*八、千古一叹"}, {"id": 596, "collection": "cy", "term": "看似寻常最奇崛，成如容易却艰辛", "chars": 14, "pinyin": "", "source": "王安石《题张司业诗》", "meaning": "*看似寻常，其实最奇崛；做成好像容易，其实最艰辛。王安石评诗，评出了人生的道理。*", "category": "*八、千古一叹"}, {"id": 597, "collection": "cy", "term": "高处不胜寒", "chars": 5, "pinyin": "", "source": "苏轼《水调歌头》", "meaning": "*高处太冷，待不住。苏轼写天上宫阙，写出了高处不胜寒的孤独。*", "category": "*八、千古一叹"}, {"id": 598, "collection": "cy", "term": "我欲乘风归去，又恐琼楼玉宇", "chars": 12, "pinyin": "", "source": "苏轼《水调歌头》", "meaning": "*我想乘风回去，又怕那琼楼玉宇太高太冷。苏轼的进退，进退得纠结。*", "category": "*八、千古一叹"}, {"id": 599, "collection": "cy", "term": "枯藤老树昏鸦，小桥流水人家", "chars": 12, "pinyin": "", "source": "马致远《天净沙·秋思》", "meaning": "***枯藤、老树、昏鸦，小桥、流水、人家。九个意象，一幅秋景，一声叹息。***", "category": "*八、千古一叹"}, {"id": 600, "collection": "cy", "term": "出师一表真名世，千载谁堪伯仲间", "chars": 14, "pinyin": "", "source": "陆游《书愤》", "meaning": "***诸葛亮的《出师表》名传千古，千年之后谁能与他比肩？***", "category": "*八、千古一叹"}];
